import re
from typing import List

def capitalize_words(string: str, capitalization: str, delimiter: str = " ") -> str:
    """
    Capitalizes the first letter of each word in `string` according to the specified `capitalization` method,
    and joins the resulting words with the specified `delimiter`.
    """
    words = string.split()
    def capitalize_word(word: str) -> str:
        if capitalization == "upper":
            return word.upper()
        elif capitalization == "lower":
            return word.lower()
        elif capitalization == "title":
            return word.title()
        else:
            raise ValueError(f"Invalid capitalization method: {capitalization}")
    capitalized_words = [capitalize_word(word) for word in words]
    return delimiter.join(capitalized_words)

