import re

def tokenize_template(template, substitutions):
    tokens = re.findall(r'\{\{(.*?)\}\}', template)
    token_names = [token.replace('{{', '').replace('}}', '').split('|')[0] for token in tokens]
    for token_name in token_names:
        if token_name not in substitutions:
            raise KeyError(f'Token name "{token_name}" is not found in the substitutions')
    for token_name in token_names:
        template = template.replace(f'{{{{{token_name}}}}}', str(substitutions[token_name]))
    return template.split()

