def row_column_reduction(matrix):
    n = len(matrix)

    for i in range(n):
        for j in range(n):
            if matrix[i][j] != 0:
                pivot_index = j
                break
        else:
            return False
        if pivot_index != i:
            for k in range(i + 1, n):
                if matrix[k][i] != 0:
                    matrix[i], matrix[k] = matrix[k], matrix[i]
                    break
            else:
                return False
        if matrix[i][i] != 1:
            pivot = matrix[i][i]
            for j in range(i, n):
                matrix[i][j] /= pivot
        for k in range(n):
            if k == i:
                continue
            factor = matrix[k][i]
            for j in range(i, n):
                matrix[k][j] -= matrix[i][j] * factor

    return True

