import re

def truncate_string_with_punctuation(string):
    string = string.lower().strip()
    words = string.split()
    if len(words) <= 200:
        return string

    first_100_words = words[:100]
    last_100_words = words[-100:]

    first_punctuation_index = -1
    for i, word in enumerate(first_100_words):
        if re.search(r"\p{P}", word):
            first_punctuation_index = i
            break

    last_punctuation_index = -1
    for i, word in enumerate(last_100_words):
        if re.search(r"\p{P}", word):
            last_punctuation_index = i
            break

    if first_punctuation_index >= 0:
        truncated_string = " ".join(first_100_words[:first_punctuation_index + 1])
    elif last_punctuation_index >= 0:
        truncated_string = " ".join(last_100_words[last_punctuation_index:])
    else:
        truncated_string = " ".join(first_100_words + last_100_words)

    return truncated_string

