class Node:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None


def parse_binary_tree(string):
    nodes = string.split(',')
    if len(nodes) == 1 and nodes[0] == '#':
        return None
    if len(nodes) == 0:
        raise ValueError('Invalid input string')
    root = Node(nodes[0])
    queue = [root]
    i = 1
    while i < len(nodes):
        node = queue.pop(0)
        if nodes[i] != '#':
            node.left = Node(nodes[i])
            queue.append(node.left)
        i += 1
        if i < len(nodes):
            if nodes[i] != '#':
                node.right = Node(nodes[i])
                queue.append(node.right)
            i += 1
    return root


def level_order_traversal(root):
    if not root:
        return []
    result = []
    queue = [root]
    while queue:
        node = queue.pop(0)
        result.append(node.value)
        if node.left:
            queue.append(node.left)
        if node.right:
            queue.append(node.right)
    return result


def parse_and_traverse(string):
    try:
        root = parse_binary_tree(string)
        return level_order_traversal(root)
    except ValueError:
        return []

