def determinant(m):
    n = len(m)
    if n == 1:
        return m[0][0]
    elif n == 2:
        return m[0][0] * m[1][1] - m[0][1] * m[1][0]
    else:
        det = 0
        for i in range(n):
            det += (-1)**i * m[0][i] * determinant(cofactor(m, 0, i))
        return det

def cofactor(m, row, col):
    n = len(m)
    cof = [[0 for _ in range(n - 1)] for _ in range(n - 1)]
    for i in range(n):
        for j in range(n):
            if i != row and j != col:
                cof[i - (i > row)][j - (j > col)] = m[i][j]
    return cof

