        for i, match in enumerate(matches, start=1):
            print(f"{i}. {match}")
        while True:
            selection = input("Select a match (1-{}): ".format(len(matches)))
            try:
                index = int(selection) - 1
                if 0 <= index < len(matches):
                    return matches[index]
                else:
                    print("Invalid selection. Please select a valid match.")
            except ValueError:
                print("Invalid input. Please input a number.")
    else:
        raise FileNotFoundError(f"No match found for '{partial_path}'")

