def max_product(values):
    max_value = float('-inf')
    max_index = -1

    for i, value in enumerate(values):
        if value > max_value:
            max_value = value
            max_index = i

    max_product = float('-inf')

    for i, value in enumerate(values):
        if i != max_index:
            product = value * max_value
            if product > max_product:
                max_product = product

    return max_product

