import os

def compare_files(path1, path2):
    result = {}
    def walk_path(path):
        for root, dirs, files in os.walk(path):
            for filename in files:
                yield os.path.join(root, filename)
            for dirname in dirs:
                yield os.path.join(root, dirname)
    for path in walk_path(path1):
        if not os.path.exists(path.replace(path1, path2)):
            result[path] = True
    for path in walk_path(path2):
        if not os.path.exists(path.replace(path2, path1)):
            result[path] = False
    return result

