class TreeNode:
    def __init__(self, val, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

class ListNode:
    def __init__(self, val, next=None):
        self.val = val
        self.next = next

def flatten_binary_tree(root):
    if not root:
        return None

    stack = [root]
    head = ListNode(root.val)
    curr = head

    while stack:
        node = stack.pop()

        if node.right:
            stack.append(node.right)
        if node.left:
            stack.append(node.left)

        if stack:
            curr.next = ListNode(stack[-1].val)
            curr = curr.next

    return head

