def split_str(str, words, stack, is_str, seen_quote):
    if not str:
        return
    if str[0] == '(' or str[0] == '[':
        stack.append(str[0])
    elif str[0] == ')' or str[0] == ']':
        stack.pop()
    if str[0] == '"':
        is_str = not is_str
        seen_quote = not seen_quote
    if str[0] == ' ' and not stack and not is_str and not seen_quote:
        split_str(str[1:], words, stack, is_str, seen_quote)
    elif str[0] != ' ':
        words[-1] += str[0]
        split_str(str[1:], words, stack, is_str, seen_quote)
    else:
        words.append('')
        split_str(str[1:], words, stack, is_str, seen_quote)

def split_words(str):
    words = ['']
    stack = []
    is_str = False
    seen_quote = False
    split_str(str, words, stack, is_str, seen_quote)
    return words

