def sort(numbers):
    if not isinstance(numbers, list):
        raise TypeError("Invalid input: expected a list of numbers.")
    for num in numbers:
        if not isinstance(num, (int, float)):
            raise TypeError("Invalid input: expected a list of numbers.")

    def merge(left, right):
        result = []
        i, j = 0, 0
        while i < len(left) and j < len(right):
            if left[i] <= right[j]:
                result.append(left[i])
                i += 1
            else:
                result.append(right[j])
                j += 1
        result += left[i:]
        result += right[j:]
        return result

    def sort_recursive(numbers):
        if not numbers:
            return numbers
        if len(numbers) == 1:
            return numbers
        mid = len(numbers) // 2
        left = sort_recursive(numbers[:mid])
        right = sort_recursive(numbers[mid:])
        return merge(left, right)

    return sort_recursive(numbers)

