def split_list_into_sublists(lst: list, num_sublists: int) -> list:
    if num_sublists <= 0:
        return []

    sublist_length = len(lst) // num_sublists

    sublists = [lst[i*sublist_length:(i+1)*sublist_length] for i in range(num_sublists)]
    if len(lst) % num_sublists:
        sublists[-1] += lst[num_sublists * sublist_length:]

    return sum(sublists, [])

