def extract_paths(tree):
    paths = []

    def traverse(node, path):
        if not node:
            return

        if not node["children"]:
            paths.append(path + [node["value"]])
        else:
            path.append(node["value"])
            for child in node["children"]:
                traverse(child, path)
            path.pop()

    traverse(tree, [])
    return paths

