def is_first_version_greater_or_equal(first: str, second: str) -> bool:
    first_revisions = first.split('.')
    second_revisions = second.split('.')
    if len(first_revisions) < len(second_revisions):
        first_revisions.extend(['0'] * (len(second_revisions) - len(first_revisions)))
    elif len(first_revisions) > len(second_revisions):
        second_revisions.extend(['0'] * (len(first_revisions) - len(second_revisions)))
    for first_revision, second_revision in zip(first_revisions, second_revisions):
        if int(first_revision) > int(second_revision):
            return True
        if int(first_revision) < int(second_revision):
            return False
    return False

