def sieve_of_eratosthenes(minimum, maximum):
    numbers = list(range(minimum, maximum + 1))
    for number in range(2, int(math.sqrt(maximum)) + 1):
        for multiple in range(number * 2, maximum + 1, number):
            if multiple in numbers:
                numbers.remove(multiple)
    return numbers

