import math

def is_prime(n, max_iterations=1000):
    if not isinstance(n, int) or n <= 1:
        raise ValueError("Input must be an integer greater than 1")
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    def square_root_approximation(x, max_iters):
        prev_guess = None
        curr_guess = x / 2

        for i in range(max_iters):
            prev_guess = curr_guess
            curr_guess = (prev_guess + x / prev_guess) / 2
            if curr_guess == prev_guess:
                break

        return curr_guess

    max_divisor = math.ceil(square_root_approximation(n, max_iterations))
    for i in range(3, max_divisor + 1, 2):
        if n % i == 0:
            return False

    return True

