    def __init__(self):
        self.parent_tags = set()

    def is_valid_parent_tag(self, tag: str) -> bool:
        if not tag.startswith("<") or not tag.endswith(">"):
            return False
        tag_name = tag[1:-1]
        if not tag_name.isalnum():
            return False
        if tag.startswith("</"):
            return tag_name in self.parent_tags
        attributes = tag_name.split(" ")
        if len(attributes) > 1:
            for attribute in attributes[1:]:
                if not attribute.startswith('"') or not attribute.endswith('"'):
                    return False
        self.parent_tags.add(tag_name)

