def parse_text_output(text_output):
    process_pattern = re.compile(r"^(?P<process_id>\d+) (?P<process_name>\w+) (?P<threads>\d+)")
    thread_pattern = re.compile(r"^(?P<thread_id>\d+) (?P<thread_name>\w+)")
