import json

def json_to_dict(json_str: str) -> dict:
    """
    Convert a JSON string to a dictionary.

    Args:
        json_str (str): The JSON string to convert.

    Returns:
        dict: A dictionary created from the JSON string.
    """
    parsed_json = json.loads(json_str)
    def convert_value(value):
        if isinstance(value, dict):
            return {convert_value(k): convert_value(v) for k, v in value.items()}
        elif isinstance(value, list):
            return [convert_value(item) for item in value]
        elif isinstance(value, str):
            return value
        elif isinstance(value, int):
            return value
        elif isinstance(value, float):
            return value
        elif isinstance(value, bool):
            return value
        elif value is None:
            return None
        else:
            raise ValueError(f"Unknown JSON value: {repr(value)}")
    return convert_value(parsed_json)

