def calculate_boolean_expression(expression: str) -> bool:
    """
    Calculates the result of a boolean expression.
    """
    expression = expression.strip()

    if expression.startswith("not"):
        return not calculate_boolean_expression(expression[3:].strip())

    for i, char in enumerate(expression):
        if char == " " or char in ["(", ")"]:
            continue
        if char in ["and", "or"]:
            left_value = calculate_boolean_expression(expression[:i].strip())
            right_value = calculate_boolean_expression(expression[i+3:].strip())
            if char == "and":
                return left_value and right_value
            else:
                return left_value or right_value
    return None

