import random

def create_random_point(mode):
    """
    Generate a random point inside a unit square or a unit circle.

    Args:
        mode (str): 'square' or 'circle' indicating the region to generate the point.

    Returns:
        A tuple representing the coordinates of the random point.
    """
    if mode == "square":
        return (random.uniform(0, 1), random.uniform(0, 1))
    elif mode == "circle":
        while True:
            x = random.uniform(-1, 1)
            y = random.uniform(-1, 1)
