def check_game_over(game_state):
    """
    Checks whether a tic-tac-toe game is over.
    Args:
        game_state (list[list[int]]): A 3x3 matrix representing the game state, where 1 represents player 1's move, 2 represents player 2's move, and 0 represents an empty space.
    Returns:
        bool: True if the game is over, False otherwise.
    """
    def check_row_col(player):
        """
        Checks whether player has three consecutive moves in a row or column.
        """
        for row in range(3):
            if game_state[row][0] == game_state[row][1] == game_state[row][2] == player:
                return True

        for col in range(3):
            if game_state[0][col] == game_state[1][col] == game_state[2][col] == player:
                return True

        return False

    def check_diag(player):
        """
        Checks whether player has three consecutive moves in a diagonal.
        """
        return (game_state[0][0] == game_state[1][1] == game_state[2][2] == player or
                game_state[0][2] == game_state[1][1] == game_state[2][0] == player)

    def check_draw():
        """
        Checks whether the game is a draw by checking if all the spaces are filled.
        """
        for row in range(3):
            for col in range(3):
                if game_state[row][col] == 0:
                    return False

        return True

    if check_row_col(1) or check_diag(1):
        return True

    if check_row_col(2) or check_diag(2):
        return True

    if check_draw():
        return True

    return False

