def lexicographic_compare(first_array, second_array):
    """
    Compares two arrays in lexicographic order. Returns True if the first array
    is lexicographically less than the second array, otherwise False.
    """
    for i in range(min(len(first_array), len(second_array))):
        if first_array[i] < second_array[i]:
            return True
        elif first_array[i] > second_array[i]:
            return False

    return len(first_array) < len(second_array)

