def utf_8_encode(code_point):
    if code_point <= 0x7F:
        return bytes([code_point])
    elif code_point <= 0x7FF:
        return bytes([(code_point >> 6) | 0xC0, (code_point & 0x3F) | 0x80])
    elif code_point <= 0xFFFF:
        return bytes([(code_point >> 12) | 0xE0, ((code_point >> 6) & 0x3F) | 0x80, (code_point & 0x3F) | 0x80])
    elif code_point <= 0x1FFFFF:
        return bytes([(code_point >> 18) | 0xF0, ((code_point >> 12) & 0x3F) | 0x80, ((code_point >> 6) & 0x3F) | 0x80, (code_point & 0x3F) | 0x80])
    else:
        raise ValueError("Invalid Unicode code point")


def convert_to_utf8(chars):
    return b"".join([utf_8_encode(ord(c)) for c in chars])

