import itertools

def levenshtein_distance(str1, str2):
    m = len(str1)
    n = len(str2)
    matrix = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m + 1):
        matrix[i][0] = i
    for j in range(n + 1):
        matrix[0][j] = j
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if str1[i-1] == str2[j-1]:
                matrix[i][j] = matrix[i-1][j-1]
            else:
                matrix[i][j] = 1 + min(matrix[i-1][j-1], matrix[i][j-1], matrix[i-1][j])
    return matrix[m][n]

def find_similar_words(word, candidate_words):
    suggested_words = []
    for candidate_word in candidate_words:
        if levenshtein_distance(word, candidate_word) <= 2:
            suggested_words.append(candidate_word)
    return suggested_words

def find_allowed_words(suggested_words, allowed_words):
    allowed_suggested_words = []
    for suggested_word in suggested_words:
        if suggested_word in allowed_words:
            allowed_suggested_words.append(suggested_word)
    return allowed_suggested_words

def correct_spelling(word, candidate_words, allowed_words):
    suggested_words = find_similar_words(word, candidate_words)
    allowed_suggested_words = find_allowed_words(suggested_words, allowed_words)
    return allowed_suggested_words

