        20: 'Twenty', 30: 'Thirty', 40: 'Forty', 50: 'Fifty', 60: 'Sixty',
        70: 'Seventy', 80: 'Eighty', 90: 'Ninety'
    }

    if number < 0 or number > 9999:
        raise ValueError('Input must be between 0 and 9999 inclusive.')
    elif number < 20:
        return digits_to_words[number]
    elif number < 100:
        tens_digit = number // 10 * 10
        ones_digit = number % 10
        if ones_digit == 0:
            return digits_to_words[tens_digit]
        else:
            return f'{digits_to_words[tens_digit]} {digits_to_words[ones_digit]}'
    elif number < 1000:
        hundreds_digit = number // 100
        remainder = number % 100
        if remainder == 0:
            return f'{digits_to_words[hundreds_digit]} Hundred'
        else:
            return f'{digits_to_words[hundreds_digit]} Hundred {number_to_english(remainder)}'
    else:
        thousands_digit = number // 1000
        remainder = number % 1000
        if remainder == 0:
            return f'{digits_to_words[thousands_digit]} Thousand'
        else:
            return f'{digits_to_words[thousands_digit]} Thousand {number_to_english(remainder)}'

