def convert_tree_to_dict(tree):
    """
    Converts a tree-like data structure into a dictionary. The tree has a root node with children nodes, similar to a filesystem.
    Each node has a name and a value, and can optionally have children nodes. The function recursively traverses the tree and
    builds a dictionary with keys as node names and values as dictionaries of the child nodes' names and values.
    """
    result_dict = {}

    def traverse(node):
        if node is None:
            return
        result_dict[node.name] = node.value
        if node.children:
            result_dict[node.name]['children'] = {}
            for child in node.children:
                traverse(child)
    traverse(tree.root)

    return result_dict

