def queens(n):
    def conflict(state, nextX):
        nextY = len(state)
        for i in range(nextY):
            if abs(state[i] - nextX) in (0, nextY - i):
                return True
        return False

    def solve(state, solutions):
        if len(state) == n:
            solutions.append(state)
        else:
            for pos in range(n):
                if not conflict(state, pos):
                    solve(state + [pos], solutions)

    solutions = []
    solve([], solutions)
    return solutions

