def is_valid_string_literal(str_literal: str) -> bool:
    """
    Validates whether a string is a valid string literal. A valid string literal
    is a string that starts and ends with a quote character, which may or may not
    be escaped. It can contain any characters within the quote characters, except
    for the quote character itself or a backslash. Returns True if the string is
    valid, otherwise False.
    """
    stack = []

    for i, char in enumerate(str_literal):
        if char == '"' or char == "'":
            if not stack or stack[-1] != char:
                stack.append(char)
            else:
                stack.pop()
        elif char == "\\":
            if i + 1 < len(str_literal) and (str_literal[i + 1] == '"' or str_literal[i + 1] == "'"):
                if not stack or stack[-1] != str_literal[i + 1]:
                    stack.append(str_literal[i + 1])
                else:
                    stack.pop()

    return not stack

