def prime_factorization(number):
    if not isinstance(number, int) or number < 0:
        raise ValueError("Input must be a non-negative integer.")

    prime_factors = []
    factor = 2

    while factor <= number:
        if number % factor == 0:
            prime_factors.append(factor)
            number //= factor
        else:
            factor += 1

