        return 1.0 / (size ** 0.5)
    elif dct_type == 'II':
        return 1.0 / ((2 * size) ** 0.5)
    elif dct_type == 'III':
        if normalized:
            return 1.0
        else:
            return 1.0 / (size ** 0.5)
    elif dct_type == 'IV':
        if normalized:
            return 1.0
        else:
