def recursive_binary_search(nums, target):
    def search(left, right):
        if left > right:
            return -1
        mid = (left + right) // 2
        if nums[mid] == target:
            return mid
        elif nums[mid] > target:
            return search(left, mid - 1)
        else:
            return search(mid + 1, right)

    return search(0, len(nums) - 1)

