from typing import Any

def traverse(data: dict, key: str) -> Any:
    """
    Traverses a hierarchical data structure and searches for a specific key.
    """
    segments = key.split('.')

    def _traverse(node: dict, segments: list) -> Any:
        if len(segments) == 0:
            return None

        segment = segments[0]
        if not isinstance(node, dict) or segment not in node:
            return None

        if len(segments) == 1:
            return node[segment]

        return _traverse(node[segment], segments[1:])

    return _traverse(data, segments)

