class Tensor:
    def __init__(self, array):
        self.array = array
        self.shape = self._get_shape(array)

        if len(self.shape) != 2:
            raise ValueError("Input tensor must be 2-dimensional.")

    def _get_shape(self, array):
        if isinstance(array, (list, tuple)):
            return (len(array),) + self._get_shape(array[0])
        return ()

    def dot(self, other):
        if self.shape[1] != other.shape[0]:
            raise ValueError("Incompatible tensor shapes.")
        result_array = [[0] * other.shape[1] for _ in range(self.shape[0])]
        for i in range(self.shape[0]):
            for j in range(other.shape[1]):
                for k in range(self.shape[1]):
                    result_array[i][j] += self.array[i][k] * other.array[k][j]
        return Tensor(result_array)

