import random

def shuffle_string(s):
    """
    Shuffles the characters in a string `s` using a state machine.
    """
    shuffled = []
    char_counts = {}
    for c in s:
        if c in char_counts:
            char_counts[c] += 1
        else:
            char_counts[c] = 1
    total_count = sum(char_counts.values())
    probabilities = {c: count / total_count for c, count in char_counts.items()}
    def sample_character():
        r = random.random()
        for c, p in probabilities.items():
            if r < p:
                return c
            r -= p
    while len(shuffled) < len(s):
        c = sample_character()
        if c in char_counts and char_counts[c] > 0:
            shuffled.append(c)
            char_counts[c] -= 1
    return ''.join(shuffled)

