def pairwise_sums(nums):
    """
    Returns a set of pairwise sums of distinct elements in the given list.
    """
    if not nums or len(nums) == 1:
        return set()
    visited = set()
    pairwise_sums = set()

    for num in nums:
        if num in visited:
            continue

        visited.add(num)

        for other_num in nums:
            if other_num in visited:
                continue

            pairwise_sums.add(frozenset([num, other_num]))

    return pairwise_sums

