import numpy as np

def epanechnikov_kernel_density_estimator(x, h, x_min, x_max):
    if not isinstance(x, np.ndarray):
        raise ValueError("x must be a numpy.ndarray")
    if not isinstance(h, (int, float)) or h < 0:
        raise ValueError("h must be a non-negative number")
    if not isinstance(x_min, (int, float)) or not isinstance(x_max, (int, float)):
        raise ValueError("x_min and x_max must be numbers")
    if x.ndim != 1:
        raise ValueError("x must be a 1-dimensional array")
    def epanechnikov_kernel(x):
        return 0.75 * (1 - x**2) * (np.abs(x) <= 1)
    x_range = np.linspace(x_min, x_max, num=x_max - x_min + 1)
    kernel_values = epanechnikov_kernel((x_range - x.reshape(-1, 1)) / h)
    density = kernel_values.sum(axis=1) / (x_range.size * h)
    density = np.where(density < 0, 0, density)
    density = np.nan_to_num(density)

    return density

