import math

def sigmoid_transformation(points, alpha=1):
    transformed_points = []
    if alpha < 0:
        raise AssertionError("alpha must be non-negative.")
    elif alpha == 0:
        raise ValueError("alpha must be non-zero.")
    elif alpha == 1:
        return points
    else:
        for point in points:
            transformed_point = 1 / (1 + math.exp(-alpha * point))
            transformed_points.append(transformed_point)
    return transformed_points

