    i = 0
    j = 0
    result = []

    while i < len(list_a) and j < len(list_b):
        if list_a[i] == list_b[j]:
            result.append(list_a[i])
            i += 1
            j += 1
        elif list_a[i] < list_b[j]:
            i = binary_search(list_a, i, len(list_a), list_b[j])
        else:
            j = binary_search(list_b, j, len(list_b), list_a[i])

    return result

def binary_search(arr, start, end, target):
    while start < end:
        mid = (start + end) // 2
        if arr[mid] < target:
            start = mid + 1
        else:
            end = mid
    return start

