def match_string_with_pattern(string: str, pattern: str) -> bool:
    if not string or not pattern:
        return False

    i, j = 0, 0

    while i < len(string) and j < len(pattern):
        if pattern[j] == "*":
            if j == len(pattern) - 1 or pattern[j + 1] != string[i]:
                return False
            j += 1
            continue

        if pattern[j] == "." or pattern[j] == string[i]:
            i += 1
            j += 1
            continue

        return False

    return i == len(string) and j == len(pattern)

