def sieve_of_eratosthenes(n):
    is_prime = [True] * n
    for i in range(2, int(n**0.5) + 1):
        if is_prime[i]:
            for j in range(i*i, n, i):
                is_prime[j] = False
    return [i for i in range(2, n) if is_prime[i]]

def is_prime(n):
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def prime_factors(n):
    if n < 2:
        return None
    if is_prime(n):
        return [n]
    factors = []
    primes = sieve_of_eratosthenes(n)
    for prime in primes:
        if n % prime == 0:
            factors.append(prime)
            n //= prime
            if n == 1:
                break
    return factors

