def geometric_series_sum(n, r):
    """
    Calculate the sum of the first n terms of a geometric series with
    common ratio r.
    """
    if r == 1:
        return n
    elif n <= 0:
        return 0
    else:
        return (1 - r**n) / (1 - r)

