import re
import datetime

def parse_datetime_timezone(input_string):
    try:
        datetime_obj = datetime.datetime.strptime(input_string, "%Y-%m-%dT%H:%M:%S%z")
    except ValueError:
        return None

    timezone_match = re.search(r'(?P<sign>[+-])(?P<hours>\d{2}):(?P<minutes>\d{2})', input_string)
    if timezone_match:
        timezone_sign = timezone_match.group('sign')
        timezone_hours = int(timezone_match.group('hours'))
        timezone_minutes = int(timezone_match.group('minutes'))
        timezone_offset = datetime.timedelta(hours=timezone_hours, minutes=timezone_minutes)
        if timezone_sign == '-':
            timezone_offset *= -1

        return (datetime_obj, timezone_offset)
    else:
        return None

