def convert_to_json_schema(data_schema):
    def _convert(value):
        if value["type"] == "string":
            return {"type": "string"}
        elif value["type"] == "integer":
            return {"type": "integer"}
        elif value["type"] == "number":
            return {"type": "number"}
        elif value["type"] == "boolean":
            return {"type": "boolean"}
        elif value["type"] == "null":
            return {"type": "null"}
        elif value["type"] == "array":
            return {"type": "array", "items": _convert(value["items"])}
        elif value["type"] == "object":
            return {"type": "object", "properties": {k: _convert(v) for k, v in value["properties"].items()}}
