from math import sqrt

def calculate_centroid_x(vertices):
    if len(vertices) < 3:
        raise Exception('Polygon must have at least three vertices.')

    def area(vertices):
        return abs(sum(vertices[i][0] * vertices[i + 1][1] - vertices[i + 1][0] * vertices[i][1]
                       for i in range(-1, len(vertices) - 1))) / 2

    if area(vertices) < 1e-6:
        raise Exception('Polygon has no area.')

