from typing import List

def check_winner(board: List[List[str]], player: str) -> bool:
    """
    Checks if the given player has won the game of Tic-Tac-Toe.
    """
    row_counts = {i: 0 for i in range(len(board))}
    col_counts = {j: 0 for j in range(len(board[0]))}
    left_diag_count, right_diag_count = 0, 0

    for i in range(len(board)):
        for j in range(len(board[0])):
            if board[i][j] == player:
                row_counts[i] += 1
                col_counts[j] += 1

                if i == j:
                    left_diag_count += 1

                if i + j == len(board) - 1:
                    right_diag_count += 1
    for count in row_counts.values():
        if count == 3:
            return True

    for count in col_counts.values():
        if count == 3:
            return True

    if left_diag_count == 3 or right_diag_count == 3:
        return True

    return False

