def detect_and_fix_casing(s: str) -> str:
    is_lowercase = all(c.islower() for c in s)
    is_uppercase = all(c.isupper() for c in s)
    is_mixedcase = not is_lowercase and not is_uppercase
    if is_lowercase:
        return s.upper()
    if is_uppercase:
        return s.lower()
    if is_mixedcase:
        fixed_case_letters = [
            letter.lower() if letter.isupper() else letter.upper()
            for letter in s
        ]
        return "".join(fixed_case_letters)

    return s

