class Library:
    def __init__(self):
        self.books = []
        self.members = {}
        self.borrowed = {}

    def add_book(self, title, author, year, copies=1):
        book = {
            'title': title,
            'author': author,
            'year': year,
            'copies': copies
        }
        self.books.append(book)

    def add_member(self, name, email):
        member = {
            'name': name,
            'email': email,
            'books': []
        }
        self.members[name] = member

    def borrow_book(self, title, member_name, due_date):
        for book in self.books:
            if book['title'] == title:
                if book['copies'] > 0:
                    book['copies'] -= 1
                    member = self.members[member_name]
                    member['books'].append(book)
                    borrowed_book = {
                        'title': book['title'],
                        'author': book['author'],
                        'year': book['year'],
                        'copies': book['copies'],
                        'member': member,
                        'due_date': due_date
                    }
                    self.borrowed[title] = borrowed_book
                    return True
                else:
                    return False

    def return_book(self, title):
        for book in self.books:
            if book['title'] == title:
                book['copies'] += 1
                member = self.borrowed[title]['member']
                member['books'].remove(book)
                del self.borrowed[title]
                return True
        return False

    def get_book(self, title):
        for book in self.books:
            if book['title'] == title:
                return book
        return None

    def get_member(self, name):
        return self.members.get(name, None)

    def get_borrowed(self, title):
        return self.borrowed.get(title, None)

    def add_copies(self, title, copies):
        book = self.get_book(title)
        if book:
            book['copies'] += copies
        else:
            self.add_book(title, copies=copies)

