def translate_cfg_node(cfg_node):
    branch_node = {}
    if cfg_node['node_type'] == 'START':
        branch_node['node_id'] = cfg_node['node_id']
        branch_node['conditions'] = []
        branch_node['statements'] = []
        branch_node['next_id'] = cfg_node['child_nodes'][0]
    elif cfg_node['node_type'] == 'END':
        branch_node['node_id'] = cfg_node['node_id']
        branch_node['conditions'] = []
        branch_node['statements'] = []
        branch_node['next_id'] = None
    elif cfg_node['node_type'] == 'CONDITION':
        condition = cfg_node['condition']
        branch_node['node_id'] = cfg_node['node_id']
        branch_node['conditions'] = [condition]
        branch_node['statements'] = []
        if condition[1] == '==':
            if condition[2] == True:
                branch_node['next_id'] = cfg_node['child_nodes'][0]
            else:
                branch_node['next_id'] = cfg_node['child_nodes'][1]
        elif condition[1] == '!=':
            if condition[2] == True:
                branch_node['next_id'] = cfg_node['child_nodes'][1]
            else:
                branch_node['next_id'] = cfg_node['child_nodes'][0]
        else:
            branch_node['next_id'] = None
    elif cfg_node['node_type'] == 'STATEMENT':
        statement = cfg_node['statement']
        branch_node['node_id'] = cfg_node['node_id']
        branch_node['conditions'] = []
        branch_node['statements'] = [statement]
        branch_node['next_id'] = cfg_node['child_nodes'][0]
    elif cfg_node['node_type'] == 'BRANCHING':
        branch_node['node_id'] = cfg_node['node_id']
        branch_node['conditions'] = []
        branch_node['statements'] = []
        for child_nodes in cfg_node['child_nodes']:
            branch_node['next_id'] = translate_cfg_node(child_nodes)
    else:
        return []
    return branch_node

