import copy

def clone_object(obj, limit=None):
    if not isinstance(obj, (list, dict, tuple)):
        return copy.copy(obj)
    if isinstance(obj, list):
        return [clone_object(item, limit) for item in obj]
    elif isinstance(obj, dict):
        return {key: clone_object(value, limit) for key, value in obj.items()}
    elif isinstance(obj, tuple):
        return tuple(clone_object(item, limit) for item in obj)
    cloned_obj = obj.__class__()  # Create an instance of the same class
    for attr in dir(obj):
        if not attr.startswith('__'):
            setattr(cloned_obj, attr, clone_object(getattr(obj, attr), limit))
    if limit is not None and limit <= 0:
        return cloned_obj
    cloned_objects = set()
    def clone_object_helper(obj, limit):
        if id(obj) in cloned_objects:
            return obj  # Return the cloned object if it is already cloned
        cloned_obj = copy.copy(obj)
        cloned_objects.add(id(obj))
        for attr in dir(obj):
            if not attr.startswith('__'):
                setattr(cloned_obj, attr, clone_object_helper(getattr(obj, attr), limit-1))
        return cloned_obj
    return clone_object_helper(obj, limit)

