def division_remainder(numerator, denominator):
    """Division using recursion."""
    if numerator < denominator:
        return 0, numerator
    quotient, remainder = division_remainder(numerator - denominator, denominator)
    return quotient + 1, remainder

def gcd(number1, number2):
    """Greatest common divisor of two numbers."""
    if number1 == 0 or number2 == 0:
        return max(number1, number2)
    quotient, remainder = division_remainder(max(number1, number2), min(number1, number2))
    if remainder == 0:
        return min(number1, number2)
    return gcd(min(number1, number2), remainder)

