def balanced_symbols(string):
    stack = []
    opening_symbols = ["(", "[", "{"]
    closing_symbols = [")", "]", "}"]
    for char in string:
        if char in opening_symbols:
            stack.append(char)
        elif char in closing_symbols:
            if not stack or opening_symbols[closing_symbols.index(char)] != stack[-1]:
                return False
            stack.pop()
        else:
            continue
    return len(stack) == 0

