def shortest_distance_dfs(graph, source, destination):
    stack = [source]
    min_distance = -1
    distances = {}
    distances[source] = 0
    visited = {}
    while stack:
        vertex = stack.pop()
        if vertex not in visited:
            visited[vertex] = True
            if vertex == destination:
                min_distance = min(min_distance, distances[vertex]) if min_distance != -1 else distances[vertex]
            else:
                for neighbor in graph[vertex]:
                    if neighbor not in visited:
                        stack.append(neighbor)
                        distances[neighbor] = distances[vertex] + 1
    return min_distance

