def maximize_sum_in_2d_list(array):
    if not array or not array[0]:
        return 0
    max_sums = [[0 for _ in range(len(array[0]))] for _ in range(len(array))]
    max_sums[0][0] = array[0][0]
    for i in range(1, len(array[0])):
        max_sums[0][i] = max_sums[0][i - 1] + array[0][i]
    for i in range(1, len(array)):
        max_sums[i][0] = max_sums[i - 1][0] + array[i][0]
    for i in range(1, len(array)):
        for j in range(1, len(array[0])):
            max_sums[i][j] = max(max_sums[i - 1][j], max_sums[i][j - 1]) + array[i][j]
