def flatten_dict(dictionary: dict) -> dict:
    """Flattens a dictionary with nested keys and returns a new dictionary with the flattened keys."""
    flattened_dict = {}

    def dfs(dictionary, current_key, flattened_dict):
        for key, value in dictionary.items():
            new_key = current_key + '.' + key if current_key else key
            if isinstance(value, dict):
                dfs(value, new_key, flattened_dict)
            else:
                flattened_dict[new_key] = value

    dfs(dictionary, '', flattened_dict)
    return flattened_dict

