class WaterBody:
    def __init__(self, depth):
        self.depth = depth
        self.neighbors = []
        self.visited = False

def count_clusters(matrix):
    water_bodies = [[WaterBody(depth) for depth in row] for row in matrix]
    for i in range(len(matrix)):
        for j in range(len(matrix[i])):
            for x, y in [(i+1, j), (i-1, j), (i, j+1), (i, j-1)]:
                if 0 <= x < len(matrix) and 0 <= y < len(matrix[x]) and water_bodies[i][j].depth == water_bodies[x][y].depth:
                    water_bodies[i][j].neighbors.append(water_bodies[x][y])
    clusters = 0
    for i in range(len(matrix)):
        for j in range(len(matrix[i])):
            if water_bodies[i][j].visited:
                continue
            clusters += 1
            visit_neighbors(water_bodies[i][j])

    return clusters

def visit_neighbors(water_body):
    water_body.visited = True
    for neighbor in water_body.neighbors:
        if not neighbor.visited:
            visit_neighbors(neighbor)

