def format_with_unit(size_in_bytes: float, unit: str) -> str:
    """
    Helper function to format a given size in bytes with a given unit.
    :param size_in_bytes: the size in bytes to be formatted.
    :param unit: the unit of the size, such as 'B', 'KB', 'MB', 'GB', or 'TB'.
    :return: a formatted string representation of the size.
    """
    if unit == 'KB':
        size_in_kb = size_in_bytes / 1024
    elif unit == 'MB':
        size_in_kb = size_in_bytes / (1024**2)
    elif unit == 'GB':
        size_in_kb = size_in_bytes / (1024**3)
    elif unit == 'TB':
        size_in_kb = size_in_bytes / (1024**4)
    else:
        size_in_kb = size_in_bytes
    rounded_size = round(size_in_kb, 1)
    return f'{rounded_size:.1f}{unit}'

def format_size(size_in_bytes: float) -> str:
    """
    Format a file size in bytes into a human-readable string representation, using 'bytes', 'KB' (kilobytes), 'MB' (megabytes), 'GB' (gigabytes), or 'TB' (terabytes) units.
    :param size_in_bytes: the size in bytes to be formatted.
    :return: a formatted string representation of the size.
    """
    if size_in_bytes < 1024:
        return format_with_unit(size_in_bytes, 'bytes')
    elif size_in_bytes < 1024**2:
        return format_with_unit(size_in_bytes, 'KB')
    elif size_in_bytes < 1024**3:
        return format_with_unit(size_in_bytes, 'MB')
    elif size_in_bytes < 1024**4:
        return format_with_unit(size_in_bytes, 'GB')
