def binary_search(lst, target):
    left = 0
    right = len(lst) - 1

    while left <= right:
        mid = (left + right) // 2
        if lst[mid] == target:
            return mid
        elif lst[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    return left

def find_next_greatest(lst, target):
    if target > lst[-1]:
        return len(lst) - 1

    return binary_search(lst, target)

