import string

def rotate_letter(letter, rotation):
    if letter.islower():
        alphabet = string.ascii_lowercase
    elif letter.isupper():
        alphabet = string.ascii_uppercase
    else:
        return letter

    return alphabet[(alphabet.index(letter) + rotation) % len(alphabet)]

def encrypt(message, rotation):
    encrypted = ''
    for letter in message:
        encrypted += rotate_letter(letter, rotation)
    return encrypted

