def compare_sequences(sequence1, sequence2):
    if not isinstance(sequence1, (list, tuple)) or not isinstance(sequence2, (list, tuple)):
        raise TypeError("Both sequences must be of type list or tuple")
    if not sequence1 and not sequence2:
        return True
    if len(sequence1) == len(sequence2):
        for element1, element2 in zip(sequence1, sequence2):
            if element1 != element2:
                return False
        return True
    if len(sequence1) < len(sequence2):
        sequence1 = sequence1 + ['?'] * (len(sequence2) - len(sequence1))
    else:
        sequence2 = sequence2 + ['?'] * (len(sequence1) - len(sequence2))
