def binary_search(lst, target):
    if not lst:
        return False, -1

    def lower_bound(lst, target):
        lo, hi = 0, len(lst) - 1
        while lo <= hi:
            mid = (lo + hi) // 2
            if lst[mid] < target:
                lo = mid + 1
            else:
                hi = mid - 1
        return lo

    i = lower_bound(lst, target)
    if i < len(lst) and lst[i] == target:
        return True, i
    else:
        return False, -1

