def fibonacci(n):
    fib_cache = {}

    def _fibonacci(n):
        if n == 0:
            return 0
        elif n == 1:
            return 1
        if n not in fib_cache:
            fib_cache[n] = _fibonacci(n - 1) + _fibonacci(n - 2)

        return fib_cache[n]
    fib_num = _fibonacci(n)
    fib_str = str(fib_num)
    return (fib_num, fib_str, len(fib_str))

