def convert_numbers(text: str) -> str:
    """
    Replaces numbers less than 1000 in a string with their word representation.
    """
    number_to_word = {
        0: 'Zero',
        1: 'One',
        2: 'Two',
        3: 'Three',
        4: 'Four',
        5: 'Five',
        6: 'Six',
        7: 'Seven',
        8: 'Eight',
        9: 'Nine',
        10: 'Ten',
