        18: 'Eighteen',
        19: 'Nineteen',
        20: 'Twenty',
        30: 'Thirty',
        40: 'Forty',
        50: 'Fifty',
        60: 'Sixty',
        70: 'Seventy',
        80: 'Eighty',
        90: 'Ninety'
    }

    def convert_tens(tens):
        if tens < 20:
            return number_to_word[tens]
        elif tens % 10 == 0:
            return number_to_word[tens]
        else:
            return number_to_word[tens // 10 * 10] + " and " + number_to_word[tens % 10]

    def convert_hundreds(hundreds):
        if hundreds < 100:
            return convert_tens(hundreds)
        else:
            return number_to_word[hundreds // 100] + " Hundred" + (" and " + convert_tens(hundreds % 100) if hundreds % 100 != 0 else "")

    def convert_thousands(thousands):
        if thousands < 1000:
            return convert_hundreds(thousands)
        else:
            return convert_hundreds(thousands // 1000) + " Thousand" + (" and " + convert_hundreds(thousands % 1000) if thousands % 1000 != 0 else "")

    def convert(number):
        if number < 1000:
            return convert_thousands(number)
        else:
            return convert_thousands(number // 1000) + " Thousand" + (" and " + convert_thousands(number % 1000) if number % 1000 != 0 else "")
    matches = re.findall(r"\d+", text)
    result = re.sub(r"\d+", lambda m: convert(int(m.group())), text)
    return result

