from typing import Dict, List, Union

def bfs_first(graph: Dict[str, List[str]], start: str, condition: str) -> Union[str, None]:
    if not graph or start not in graph:
        return None

    queue = [start]
    visited = set(start)

    while queue:
        node = queue.pop(0)

        if condition(node):
            return node

        for neighbor in graph[node]:
            if neighbor not in visited:
                queue.append(neighbor)
                visited.add(neighbor)

    return None

