def find_max_recursive(numbers: List[int]) -> Optional[int]:
    if not numbers:
        return None
    if len(numbers) == 1:
        return numbers[0]

    mid = len(numbers) // 2
    left_max = find_max_recursive(numbers[:mid])
    right_max = find_max_recursive(numbers[mid:])
