def solve_sudoku(board):
    def find_empty(board):
        for i in range(9):
            for j in range(9):
                if board[i][j] == 0:
                    return i, j
        return None, None
    def valid(board, value, row, col):
        for i in range(9):
            if board[row][i] == value:
                return False
        for i in range(9):
            if board[i][col] == value:
                return False
        square_row = (row // 3) * 3
        square_col = (col // 3) * 3
        for i in range(3):
            for j in range(3):
                if board[square_row + i][square_col + j] == value:
                    return False
        return True
    def backtrack(board):
        row, col = find_empty(board)
        if row is None:
            return True
        for value in range(1, 10):
            if valid(board, value, row, col):
                board[row][col] = value
                if backtrack(board):
                    return True
                board[row][col] = 0
        return False

    return backtrack(board)

