import urllib.parse

def validate_and_extract_url_components(url: str) -> str:
    parsed_url = urllib.parse.urlparse(url)
    if not parsed_url.scheme or not (parsed_url.scheme == 'http' or parsed_url.scheme == 'https'):
        return f"Invalid scheme: '{parsed_url.scheme}'. The URL must start with 'http://' or 'https://'."
    if not parsed_url.netloc:
        return 'Invalid URL: The host is missing.'
    for segment in parsed_url.path.split('/'):
        if not segment:
            return f"Invalid segment: '{segment}'. Path segments must be non-empty."
    if parsed_url.query:
        for pair in parsed_url.query.split('&'):
            if '=' not in pair:
                return f"Invalid query string: '{pair}'. Query string pairs must be in the form 'key=value'."
            key, value = pair.split('=')
            if not key or not value:
                return f"Invalid query string pair: '{pair}'. Keys and values must be non-empty."
    components = []
    if parsed_url.scheme:
        components.append(parsed_url.scheme)
    if parsed_url.netloc:
        components.append(parsed_url.netloc)
    if parsed_url.path:
        components.append(parsed_url.path)
    if parsed_url.query:
        components.append('?' + parsed_url.query)
    if parsed_url.fragment:
        components.append('#' + parsed_url.fragment)
    return '/'.join(components)

