class IntMap:
    def __init__(self):
        self.count = {}
        self.order = []

    def put(self, x):
        if x not in self.count:
            self.count[x] = 1
            self.order.append(x)
        else:
            self.count[x] += 1

    def get(self, x):
        return self.count.get(x, 0)

    def remove_first(self):
        first = self.order[0]
        del self.count[first]
        self.order.remove(first)
        return first

    def __iter__(self):
        return IntMapIterator(self)

class IntMapIterator:
    def __init__(self, intmap):
        self.intmap = intmap
        self.index = 0

    def __next__(self):
        if self.index >= len(self.intmap.order):
            raise StopIteration
        x = self.intmap.order[self.index]
        self.index += 1
        return x

