    if hex_string.startswith('-'):
        negative = True
        hex_string = hex_string[1:]  # Remove the sign prefix
    else:
        negative = False
    decimal_digits = []
    for digit in hex_string:
        decimal_digits.append(int(digit, 16))
    decimal_number = 0
    for i, digit in enumerate(reversed(decimal_digits)):
        decimal_number += digit * 16 ** i

