def get_prime_factors(n, limit=None):
    if n < 2:
        return None  # Invalid input
    if limit is None:
        limit = n
    prime = [True] * (limit + 1)
    sqr_root = int(limit ** 0.5)
    for num in range(2, sqr_root + 1):
        if prime[num]:
            for multiple in range(num * 2, limit + 1, num):
                prime[multiple] = False
    prime_factors = set(num for num in range(2, limit + 1) if prime[num] and n % num == 0)
