def levenshtein_distance(s1, s2):
    cache = {}
    def recursive_levenshtein(s1, s2):
        if s1 == s2:
            return 0
        if not s1 or not s2:
            return len(s1 or s2)
        if s1[-1] == s2[-1]:
            return recursive_levenshtein(s1[:-1], s2[:-1])
        key = s1 + '|' + s2
        if key not in cache:
            cache[key] = 1 + min(
                recursive_levenshtein(s1[:-1], s2),     # Insert
                recursive_levenshtein(s1[:-1], s2[:-1]), # Delete
                recursive_levenshtein(s1, s2[:-1]),     # Substitute
            )
        return cache[key]

    return recursive_levenshtein(s1, s2)

