import re

def apply_replacements(template, replacements):
    replacement_regex = re.compile(r'{([^}]+)}')
    def apply_replacements_recursive(string):
        match = replacement_regex.search(string)
        if match:
            key, value = match.group(1), replacements.get(match.group(1))
            if value:
                value = apply_replacements_recursive(value)
                string = string.replace(f'{{{key}}}', value, 1)
            return apply_replacements_recursive(string)
        else:
            return string
    return apply_replacements_recursive(template)

