            values.extend(range(60))  # Add all possible values
        elif "-" in element:
            start, end = element.split("-")
            values.extend(range(int(start), int(end)+1))  # Add range of values
        elif "/" in element:
            start, interval = element.split("/")
            if start.isdigit():
                values.extend(range(int(start), 60, int(interval)))  # Add range of values with interval
