def extract_names(object: dict or list) -> str:
    """
    Extracts all 'name' values from a JSON object and returns a single string
    that contains a list of all values. If the 'name' key is not present in a
    dictionary, skip it. If the 'name' key is present but empty, output the key
    and an empty string. If the 'name' key is present but not a string, output
    the key and the value as a string.
    """

    def extract_names_recursive(object: dict or list, output: list) -> None:
        if isinstance(object, dict):
            if 'name' in object:
                if object['name'] == '':
                    output.append('name: ""')
                elif isinstance(object['name'], str):
                    output.append(f"name: {object['name']}")
                else:
                    output.append(f"name: {str(object['name'])}")
            for value in object.values():
                if isinstance(value, (dict, list)):
                    extract_names_recursive(value, output)
        elif isinstance(object, list):
            for value in object:
                if isinstance(value, (dict, list)):
                    extract_names_recursive(value, output)

    output = []
    extract_names_recursive(object, output)
    return ', '.join(output)

