def factorial(n: int) -> int:
    if n < 0:
        raise ValueError("Factorial is undefined for negative numbers.")
    elif n == 0 or n == 1:
        return 1
    else:
        return n * factorial(n - 1)

def is_strong_number(number: int) -> bool:
    temp = number
    sum_factorial = 0

    while temp > 0:
        digit = temp % 10
        sum_factorial += factorial(digit)
        temp //= 10

    return sum_factorial == number

