def recursive_binary_search(nums, target):
    """
    Searches for `target` in `nums` using a recursive binary search algorithm.
    Returns the index of the element if found, or -1 if the element is not in the array.
    """
    return recursive_binary_search_helper(nums, target, 0, len(nums) - 1)


def recursive_binary_search_helper(nums, target, left, right):
    if left > right:
        return -1
    mid = (left + right) // 2
    if nums[mid] == target:
        return mid
    elif nums[mid] < target:
        return recursive_binary_search_helper(nums, target, mid + 1, right)
    else:
        return recursive_binary_search_helper(nums, target, left, mid - 1)

