def elementwise_matrix_multiplication(A, B):
    if len(A) != len(B) or len(A[0]) != len(B[0]):
        raise ValueError("The size of A and B does not match.")
    result = [[0 for _ in range(len(A[0]))] for _ in range(len(A))]
    for i in range(len(A)):
        for j in range(len(A[0])):
            result[i][j] = A[i][j] * B[i][j]
    return result

def columnwise_matrix_multiplication(A, B):
    if len(A[0]) != len(B):
        raise ValueError("The number of columns of A does not match the number of rows of B.")
    result = [[0 for _ in range(len(B[0]))] for _ in range(len(A))]
    for i in range(len(A)):
        for j in range(len(B[0])):
            for k in range(len(B)):
                result[i][j] += A[i][k] * B[k][j]
    return result

def rowwise_matrix_multiplication(A, B):
    if len(A) != len(B[0]):
        raise ValueError("The number of rows of A does not match the number of columns of B.")
    result = [[0 for _ in range(len(B[0]))] for _ in range(len(A))]
    for i in range(len(A)):
        for j in range(len(B[0])):
            for k in range(len(B)):
                result[i][j] += A[i][k] * B[j][k]
    return result

