def longest_balanced(string):
    stack = []
    max_length = 0
    start_index = 0
    end_index = 0

    for i, char in enumerate(string):
        if char == '(':
            stack.append(i)
        elif char == ')':
            if len(stack) == 0:
                length = i - start_index
                if length > max_length:
                    max_length = length
            else:
                stack.pop()
                if len(stack) == 0:
                    length = i - start_index + 1
                    if length > max_length:
                        max_length = length
                        start_index = i - length + 1
                        end_index = i + 1

    return string[start_index:end_index]

