def convert_to_table(data):
    if not data:
        return ""

    headers = data[0].keys()
    columns = zip(*data)
    column_lengths = [max(map(len, str(value))) for value in columns]
    header_lengths = [max(map(len, header)) for header in headers]

    def format_value(value):
        if value is None:
            return " " * max(column_lengths)
        return str(value).ljust(max(column_lengths, key=len))

    def format_header(header):
        return header.ljust(max(header_lengths, key=len))

    formatted_headers = "  ".join(map(format_header, headers))
    formatted_data = [
        "  ".join(map(format_value, row)) for row in data
    ]

    return formatted_headers + "\n" + "\n".join(formatted_data)

