def unique_elements(lst):
    result = []
    lst.sort()

    for n in lst:
        if binary_search(result, n) == -1:
            result.append(n)

    return result

def binary_search(lst, x):
    low = 0
    high = len(lst) - 1

    while low <= high:
        mid = low + (high - low) // 2

        if lst[mid] == x:
            return mid
        elif lst[mid] < x:
            low = mid + 1
        else:
            high = mid - 1

    return -1

