        local_vars = {var_name: var_value for var_name, var_value in closure_vars.locals.items()}
    elif inspect.isclass(func):
        for method_name, method in inspect.getmembers(func, predicate=inspect.isfunction):
            closure_vars = inspect.getclosurevars(method)
            local_vars[method_name] = {var_name: var_value for var_name, var_value in closure_vars.locals.items()}
    else:
        raise TypeError("The argument must be a function, method, or class")
    defining_class = getattr(func, "__qualname__", None) or getattr(func, "__self__", None) or func.__module__
    return {defining_class: local_vars}

