def find_lcs(seq1, seq2):
    n = len(seq1)
    m = len(seq2)
    memo = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if seq1[i - 1] == seq2[j - 1]:
                memo[i][j] = memo[i - 1][j - 1] + 1
            else:
                memo[i][j] = max(memo[i - 1][j], memo[i][j - 1])
    lcs = []
    i = n
    j = m
    while i > 0 and j > 0:
        if seq1[i - 1] == seq2[j - 1]:
            lcs.append(seq1[i - 1])
            i -= 1
            j -= 1
        else:
            if memo[i - 1][j] > memo[i][j - 1]:
                i -= 1
            else:
                j -= 1

    lcs.reverse()

    return memo[n][m], lcs

