def extract_tokens(tree):
    tokens = []
    current_index = 0

    def traverse_node(node):
        nonlocal current_index
        if isinstance(node, list):
            for item in node:
                traverse_node(item)
            if current_index < len(node) - 1:
                tokens.append(node[-1])
        elif isinstance(node, tuple):
            for item in node:
                traverse_node(item)
            if current_index < len(node) - 1:
                tokens.append(node[-1])
        elif isinstance(node, dict):
            for key, value in node.items():
                traverse_node(key)
                traverse_node(value)
        else:
            tokens.append(node)

        current_index += 1

    traverse_node(tree)
    return tokens

