def bisection(f, x1, x2, tol=1e-6):
    if not callable(f):
        raise ValueError("f must be a function")
    if x1 >= x2:
        raise ValueError("x1 must be less than x2")

    def check_root(xm):
        if abs(f(xm)) < tol:
            return xm
        return None

    xm = (x1 + x2) / 2.0
    root = check_root(xm)
    if root is not None:
        return root

    if f(x1) * f(xm) < 0:
        return bisection(f, x1, xm, tol)
    elif f(xm) * f(x2) < 0:
        return bisection(f, xm, x2, tol)
    else:
        raise ValueError("Root not found within the given interval")

