def resolve_dependencies(dependency_dict):
    visited = {}
    result = []
    def dfs(package):
        if package in visited:
            return
        visited[package] = True
        dependencies = dependency_dict.get(package, [])
        for dep in dependencies:
            dfs(dep)
        result.append(package)
    for package in dependency_dict:
        dfs(package)
    return result

