from collections import Counter

def single_round_election(ballots):
    votes = Counter()
    for ballot in ballots:
        first_choice = ballot[0]
        votes[first_choice] += 1
    runoff_candidates = None
    if not any(vote > len(ballots) / 2 for vote in votes.values()):
        runoff_candidates = [candidate for candidate, vote in votes.most_common(2)]
    while runoff_candidates:
        for tied_candidate in runoff_candidates:
            ballots = [ballot for ballot in ballots if ballot[0] != tied_candidate]
        for ballot in ballots:
            if ballot[0] == ballot[1]:
                continue
            votes[ballot[1]] += 1
        if any(vote > len(ballots) / 2 for vote in votes.values()):
            break
        runoff_candidates = [candidate for candidate, vote in votes.most_common(2)]
    winner = max(votes, key=votes.get)
    return winner

