def least_common_multiple(numbers):
    """
    Find the least common multiple (LCM) of a list of numbers.

    Parameters:
    numbers (list): A list of integers.

    Returns:
    int: The least common multiple of the numbers in the list.
    """
    prime_factors = {}
    for n in numbers:
        factors = {}
        num = n
        i = 2
        while num > 1:
            if num % i == 0:
                if i in factors:
                    factors[i] += 1
                else:
                    factors[i] = 1
                num = num // i
            else:
                i += 1
        for prime_factor in factors:
            if prime_factor in prime_factors:
                prime_factors[prime_factor] = max(prime_factors[prime_factor], factors[prime_factor])
            else:
                prime_factors[prime_factor] = factors[prime_factor]

    lcm = 1
    for prime_factor in prime_factors:
        lcm *= prime_factor ** prime_factors[prime_factor]
    return lcm

