import json
from typing import Any, List

def parse_json_object(json_string: str, key_path: List[str]) -> Any:
    """
    Parses a JSON object and returns the value corresponding to the given key path. If
    the key path is invalid or the corresponding value is not found, returns `None`.
    """
    try:
        json_obj = json.loads(json_string)
    except json.JSONDecodeError:
        return None

    def _parse_json_object_recursive(obj, keys):
        if not keys:
            return obj

        if isinstance(obj, dict):
            key = keys[0]
            if key in obj:
                return _parse_json_object_recursive(obj[key], keys[1:])
        return None

    return _parse_json_object_recursive(json_obj, key_path)

