def longest_common_subsequence(s1: str, s2: str) -> int:
    memo = {}

    def helper(i: int, j: int) -> int:
        if (i, j) not in memo:
            if i == len(s1) or j == len(s2):
                memo[(i, j)] = 0
            elif s1[i] == s2[j]:
                memo[(i, j)] = 1 + helper(i + 1, j + 1)
            else:
                memo[(i, j)] = max(helper(i + 1, j), helper(i, j + 1))
        return memo[(i, j)]

