def convert_base(num, source_base, target_base):
    if num < 0 or source_base < 2 or target_base < 2:
        raise ValueError("Invalid input")
    previous_results = {}
    def to_decimal(num, base):
        if num in previous_results:
            return previous_results[num]
        if num < base:
            return num
        previous_results[num] = base * to_decimal(num // base, base) + (num % base)
        return previous_results[num]

    def from_decimal(num, base):
        if num < base:
            return str(num)
        return from_decimal(num // base, base) + str(num % base)
    decimal_num = to_decimal(num, source_base)
    result = from_decimal(decimal_num, target_base)

    return result

