import asyncio
from functools import wraps

class AsyncLoopContextManager:
    def __init__(self):
        self._loop = None

    def __enter__(self):
        self._loop = asyncio.new_event_loop()
        asyncio.set_event_loop(self._loop)
        return self._loop

    def __exit__(self, exc_type, exc_val, exc_tb):
        self._loop.close()
        asyncio.set_event_loop(None)

def async_loop_decorator(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        async def _func(*args, **kwargs):
            return await func(*args, **kwargs)
        with AsyncLoopContextManager() as loop:
            return loop.run_until_complete(_func(*args, **kwargs))
    return wrapper

