def check_dataset_sanity(col1, col2, tolerance=None):
    """
    Check the sanity of a given dataset by comparing the contents of two columns.

    Args:
        col1 (list or series): First column of data.
        col2 (list or series): Second column of data.
        tolerance (float, optional): Tolerance value for numerical comparisons. Defaults to None.

    Returns:
        bool: True if the data is sane, False otherwise.
    """
    if (col1 is None) or (col2 is None):
        return False
    if isinstance(col1[0], str):
        col1 = [x.lower() for x in col1]
        col2 = [x.lower() for x in col2]
    elif (isinstance(col1[0], int) or isinstance(col1[0], float)) and tolerance is not None:
        col1 = [float(x) for x in col1]
        col2 = [float(x) for x in col2]
    num_unique_col1 = len(set(col1))
    num_unique_col2 = len(set(col2))
    if num_unique_col1 != num_unique_col2:
        return False
    if isinstance(col1[0], str):
        return sorted(col1) == sorted(col2)
    elif isinstance(col1[0], int) or isinstance(col1[0], float):
        return all(abs(col1[i] - col2[i]) <= tolerance for i in range(len(col1)))
    else:
        return False

