    compressed = ""
    prev_char = ""
    count = 0

    for c in s:
        if c == prev_char:
            count += 1
        else:
            if count > 1:
                compressed += prev_char + str(count)
            else:
                compressed += prev_char
            prev_char = c
            count = 1

    if count > 1:
        compressed += prev_char + str(count)
    else:
        compressed += prev_char

