    if not isinstance(array, list) or not isinstance(k, int):
        raise TypeError('Invalid input')
    if k < 1:
        raise ValueError('k must be a positive integer')
    if len(array) < k:
        raise ValueError('k cannot be greater than the number of unique elements in the array')
    frequency_dict = {}
    for element in array:
        if element in frequency_dict:
