class BinaryTree:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None

def build_dict(root: BinaryTree) -> dict:
    if not isinstance(root, BinaryTree):
        raise ValueError("Invalid binary tree provided.")
    dictionary = {}
    def traverse(node: BinaryTree, depth: int):
        if not node:
            return
        dictionary.setdefault(depth, []).append(node.value)
        traverse(node.left, depth + 1)
        traverse(node.right, depth + 1)
    traverse(root, 0)
    return dictionary

