import random

def randomized_quick_select(array, k):
    if len(array) == 1:
        return array[0]

    pivot_index = random.randint(0, len(array) - 1)
    pivot_value = array[pivot_index]

    left = [x for x in array if x < pivot_value]
    right = [x for x in array if x > pivot_value]

    if k < len(left):
        return randomized_quick_select(left, k)
    elif k > len(left):
        return randomized_quick_select(right, k - len(left) - 1)
    else:
        return pivot_value

