import re

def match_pattern(pattern, string):
    pattern_tokens = re.split(r'(\.|\+|\(|\))', pattern)  # Split the pattern into tokens
    function_closures = {
        '.': _match_wildcard,
        '+': _match_quantifier,
        '(': _match_grouping,
    }

    def match_token(string, token):
        if token in function_closures:
            return function_closures[token](string)
        else:
            return _match_literal(string, token)

    for token in pattern_tokens:
        if not match_token(string, token):
            return False

    return True  # All tokens matched

def _match_wildcard(string):
    if string:
        return string[1:]
    return string

def _match_quantifier(string):
    if string:
        return string[1:]
    return string

def _match_grouping(string):
    if string:
        return string[1:]
    return string

def _match_literal(string, token):
    if string.startswith(token):
        return string[len(token):]
    return string

