def subtract(c1, c2):
    """Subtract two complex numbers."""
    real = c1[0] - c2[0]
    imag = c1[1] - c2[1]
    return (real, imag)

def multiply(c1, c2):
    """Multiply two complex numbers."""
    real = c1[0] * c2[0] - c1[1] * c2[1]
    imag = c1[0] * c2[1] + c1[1] * c2[0]
    return (real, imag)

def divide(c1, c2):
    """Divide two complex numbers."""
    real = (c1[0] * c2[0] + c1[1] * c2[1]) / (c2[0] ** 2 + c2[1] ** 2)
    imag = (c1[1] * c2[0] - c1[0] * c2[1]) / (c2[0] ** 2 + c2[1] ** 2)
    return (real, imag)

def power(c, n):
    """Raise a complex number to a given integer power."""
    real = c[0]
    imag = c[1]
    for i in range(1, n):
        real, imag = multiply((real, imag), c)
    return (real, imag)

