def find_first_and_last_position(array, target):
    def binary_search(array, target):
        low, high = 0, len(array) - 1
        while low <= high:
            mid = (low + high) // 2
            if array[mid] < target:
                low = mid + 1
            elif array[mid] > target:
                high = mid - 1
            else:
                return mid
        return -1

    index = binary_search(array, target)
    if index == -1:
        return (-1, -1)

    first_index = index
    while first_index > 0 and array[first_index - 1] == target:
        first_index -= 1

    last_index = index
    while last_index < len(array) - 1 and array[last_index + 1] == target:
        last_index += 1

    return (first_index, last_index)

