        raise ValueError("Invalid number")

def extract_and_sum_numbers(string: str) -> int:
    first_number = re.search(r"\d+", string)
    if not first_number:
        return None
    try:
        validate_number(first_number.group())
    except ValueError as e:
        print(f"Validation failed: {e}")
        return None
    total = 0
    for match in re.finditer(r"\d+", string):
        total += int(match.group())
    return total

