def solve_sudoku(board):
    def is_valid(row, col, num):
        for i in range(9):
            if board[row][i] == num or board[i][col] == num:
                return False
        sub_row = row - row % 3
        sub_col = col - col % 3
        for i in range(3):
            for j in range(3):
                if board[sub_row + i][sub_col + j] == num:
                    return False
        return True
    def solve(row=0, col=0):
        if row == 8 and col == 9:
            return True
        if col == 9:
            row += 1
            col = 0
        if board[row][col] != 0:
            return solve(row, col + 1)
        for num in range(1, 10):
            if is_valid(row, col, num):
                board[row][col] = num
                if solve(row, col + 1):
                    return True
            board[row][col] = 0
        return False
    solve()
    return board

