def decode_string(encoded_string):
    language, data_type = encoded_string.split('_')
    function_map = {
        'python': {
            'json': decode_python_json,
            'base64': decode_python_base64,
            'binary': decode_python_binary
        },
        'rust': {
            'json': decode_rust_json,
            'base64': decode_rust_base64,
            'binary': decode_rust_binary
        },
        'js': {
            'json': decode_js_json,
            'base64': decode_js_base64,
            'binary': decode_js_binary
        }
    }
    decoded_string = function_map[language][data_type](encoded_string)
