def shortest_path(graph, start, end):
    visited = set()
    stack = [(start, [start])]
    while stack:
        node, path = stack.pop()
        if node not in visited:
            visited.add(node)
            if node == end:
                return path
            for neighbor in graph[node]:
                if neighbor not in visited:
                    stack.append((neighbor, path + [neighbor]))
    return []

