def round_incomes(incomes):
    rounded_incomes = [round_to_multiple(income, 500) for income in incomes]
    if sum(rounded_incomes) < sum(incomes):
        lowest_index = rounded_incomes.index(min(rounded_incomes))
        rounded_incomes[lowest_index] += 500
        return round_incomes(rounded_incomes)
    elif sum(rounded_incomes) > sum(incomes):
        highest_index = rounded_incomes.index(max(rounded_incomes))
        rounded_incomes[highest_index] -= 500
        return round_incomes(rounded_incomes)
    else:
        return rounded_incomes

def round_to_multiple(income, multiple):
    if income % multiple == 0:
        return income
    elif income // multiple > 0:
        return (income // multiple + 1) * multiple
    else:
        return (income // multiple - 1) * multiple

