def is_same(obj1, obj2):
    if obj1 is None or obj2 is None:
        return obj1 is obj2
    if obj1 != obj1 or obj2 != obj2:
        return obj1 != obj1 and obj2 != obj2
    if obj1 == float('inf') and obj2 == float('inf'):
        return True
    if obj1 == float('-inf') and obj2 == float('-inf'):
        return True
    if obj1 == float('nan') or obj2 == float('nan'):
        return False
    if obj1 == float('-0.0') and obj2 == float('-0.0'):
        return True
    if type(obj1) in (tuple, list) and type(obj2) in (tuple, list):
        return len(obj1) == len(obj2) and all(is_same(x, y) for x, y in zip(obj1, obj2))
    if type(obj1) is dict and type(obj2) is dict:
        return len(obj1) == len(obj2) and all(is_same(obj1[key], obj2[key]) for key in obj1)
    return obj1 == obj2

