def insertion_sort(lst, reverse=False):
    def insert(lst, i, reverse=False):
        if i > 0:
            if reverse:
                if lst[i] > lst[i-1]:
                    lst[i-1], lst[i] = lst[i], lst[i-1]
                    insert(lst, i-1, reverse)
            else:
                if lst[i] < lst[i-1]:
                    lst[i-1], lst[i] = lst[i], lst[i-1]
                    insert(lst, i-1, reverse)

    for i in range(1, len(lst)):
        insert(lst, i, reverse)

