import ast

def format_function(input_string: str) -> str:
    tree = ast.parse(input_string)
    func_def = next(ast.iter_child_nodes(tree, ast.FunctionDef), None)

    if func_def:
        name = func_def.name
        args = func_def.args
        return_type = func_def.returns
        body = func_def.body
        formatted_body = ""
        for stmt in body:
            if isinstance(stmt, ast.If):
                formatted_body += "    " + ast.unparse(stmt) + "\n"
            elif isinstance(stmt, ast.Try):
                formatted_body += "    " + ast.unparse(stmt) + "\n"
            else:
                formatted_body += "    " + ast.unparse(stmt).strip() + "\n"
        func_def_string = f"def {name}({ast.unparse(args)}) -> {ast.unparse(return_type)}:\n{formatted_body}"
        return func_def_string.strip()
    else:
        raise ValueError("Invalid function definition")

