def xml_escape_sequence_converter(string):
    xml_escape_sequences = {
        '&amp;': '&',
        '&lt;': '<',
        '&gt;': '>',
        '&apos;': "'",
        '&quot;': '"',
    }
    xml_special_characters_regex = re.compile('|'.join(xml_escape_sequences.values()))
    xml_escape_sequences_regex = re.compile('|'.join(xml_escape_sequences.keys()))
    def convert_xml_escape_sequences(match):
        for special_character, escape_sequence in xml_escape_sequences.items():
            if match.group(0) == special_character:
                return escape_sequence
        return match.group(0)
    def convert_special_characters_to_escape_sequences(match):
        for special_character, escape_sequence in xml_escape_sequences.items():
            if match.group(0) == escape_sequence:
                return special_character
        return match.group(0)
    converted_string = xml_special_characters_regex.sub(convert_xml_escape_sequences, string)
    converted_string = xml_escape_sequences_regex.sub(convert_special_characters_to_escape_sequences, converted_string)

