import random

def generate_isbn():
    isbn = ''

    for i in range(9):
        digit = random.randint(0, 9)
        isbn += str(digit)

    check_digit = calculate_check_digit(isbn)

    if check_digit == 10:
        isbn += 'X'
    else:
        isbn += str(check_digit)

    return isbn

def calculate_check_digit(isbn):
    total = 0

    for i, digit in enumerate(isbn):
        weight = 10 - i
        total += int(digit) * weight

    remainder = total % 11
    if remainder == 10:
        return 0
    return remainder

def validate_isbn(isbn):
    if len(isbn) != 10:
        return False

    check_digit = calculate_check_digit(isbn[:-1])
    if isbn[-1] == 'X' and check_digit == 0:
        return True
    elif str(check_digit) == isbn[-1]:
        return True
    return False

