def ip_to_canonical(ip_address):
    if '.' in ip_address:  # IPv4
        segments = ip_address.split('.')
        if len(segments) == 4:
            canonical = []
            for segment in segments:
                try:
                    value = int(segment)
                    if 0 <= value <= 255:
                        canonical.append(str(value))
                    else:
                        return None
                except ValueError:
                    return None
            return '.'.join(canonical)
    elif ':' in ip_address:  # IPv6
        segments = ip_address.split(':')
        if len(segments) == 8:
            canonical = []
            for segment in segments:
                try:
                    value = int(segment, 16)
                    canonical.append(hex(value)[2:])
                except ValueError:
                    return None
            return ':'.join(canonical)
    return None

