import math

def all_pairs_shortest_path(graph):
    num_nodes = len(graph)
    dist = [[math.inf] * num_nodes for _ in range(num_nodes)]
    for i in range(num_nodes):
        dist[i][i] = 0
    for u in graph:
        i = ord(u) - ord('A')
        for v, cost in graph[u]:
            j = ord(v) - ord('A')
            dist[i][j] = cost
    for k in range(num_nodes):
        for i in range(num_nodes):
            for j in range(num_nodes):
                dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j])
    result = {}
    for i in range(num_nodes):
        for j in range(num_nodes):
            u = chr(i + ord('A'))
            v = chr(j + ord('A'))
            result[(u, v)] = dist[i][j]

    return result

