def min_steps(grid):
    m = len(grid)
    n = len(grid[0])
    dp = [[-1 for _ in range(n)] for _ in range(m)]
    def f(i, j):
        if i < 0 or j < 0:
            return float('inf')
        if i == 0 and j == 0:
            return grid[0][0]
        if dp[i][j] != -1:
            return dp[i][j]
        dp[i][j] = grid[i][j] + min(f(i - 1, j), f(i, j - 1))
        return dp[i][j]
    min_steps = f(m - 1, n - 1)
    if min_steps == float('inf'):
        return -1
    return min_steps

