import math

def get_first_n_unique_primes(n):
    is_prime = [True] * (n ** 2 + 1)
    is_prime[0] = False
    is_prime[1] = False
    for i in range(2, int(math.sqrt(n ** 2)) + 1):
        if is_prime[i]:
            for j in range(i * i, n ** 2 + 1, i):
                is_prime[j] = False
    primes = []
    count = 0
    for i in range(n ** 2 + 1):
        if is_prime[i] and i not in primes:
            primes.append(i)
            count += 1
