import numpy as np

def cumsum_2d(a: np.ndarray) -> np.ndarray:
    if a.ndim == 1:
        return np.cumsum(a)
    elif a.ndim == 2:
        return np.cumsum(a, axis=1)
    else:
        result = np.empty_like(a)
        for i in range(a.shape[0]):
            for j in range(a.shape[1]):
                result[i, j] = cumsum_2d(a[i, j])
