import functools
import logging

def log_decorator(f):
    @functools.wraps(f)
    def wrapper(*args, **kwargs):
        logging.info(f'Calling function {f.__name__} with args {args} and kwargs {kwargs}')
        result = f(*args, **kwargs)
        logging.info(f'Function {f.__name__} returned {result}')
        return result
    return wrapper

def retry_decorator(f, max_retries=3):
    @functools.wraps(f)
    def wrapper(*args, **kwargs):
        retry_count = 0
        while retry_count < max_retries:
            try:
                return f(*args, **kwargs)
            except Exception as e:
                logging.error(f'Function {f.__name__} failed with {e}, retrying...')
                retry_count += 1
        logging.error(f'Function {f.__name__} failed after {max_retries} retries, giving up...')
        raise
    return wrapper

@log_decorator
@retry_decorator
def my_function(a, b):
    return a + b

