def decode_bytecode(bytecode):
    assembly_code = []
    for instruction in bytecode:
        opcode = instruction['opcode']
        arguments = instruction['arguments']
        if opcode == 1:
            assembly_code.append('nop')
        elif opcode == 2:
            assembly_code.append(f'add {arguments[0]}, {arguments[1]}')
        elif opcode == 3:
            assembly_code.append(f'sub {arguments[0]}, {arguments[1]}')
        elif opcode == 4:
            assembly_code.append(f'mul {arguments[0]}, {arguments[1]}')
        elif opcode == 5:
            assembly_code.append(f'div {arguments[0]}, {arguments[1]}')
        else:
            raise ValueError('Invalid opcode')

    return assembly_code

