    relevant_documents = retrieve_documents(query)
    scored_documents = [(calculate_similarity(query, doc), doc) for doc in relevant_documents]
    sorted_documents = sorted(scored_documents, key=lambda x: x[0], reverse=True)
    if sorted_documents:
        return sorted_documents[0][1]
    else:
        return None

