import hashlib
import hmac

def verify_hmac(message, key, provided_hmac):
    if isinstance(message, str):
        message = message.encode()
    elif isinstance(message, bytearray):
        message = bytes(message)

    if isinstance(key, str):
        key = key.encode()
    elif isinstance(key, bytearray):
        key = bytes(key)

    if isinstance(provided_hmac, str):
        provided_hmac = provided_hmac.encode()
    elif isinstance(provided_hmac, bytearray):
        provided_hmac = bytes(provided_hmac)
    calculated_hmac = hmac.new(key, message, hashlib.sha256).digest()
