import json

def handle_rpc_request(rpc_request):
    request_dict = json.loads(rpc_request)
    if request_dict['method'] not in ['add', 'sub', 'mul', 'div']:
        return json.dumps({'error': 'Method not recognized'})
    if not all(param in request_dict for param in ['params', 'id']):
        return json.dumps({'error': 'Missing required parameters'})
    params = request_dict['params']
    result = None
    if request_dict['method'] == 'add':
        result = params[0] + params[1]
    elif request_dict['method'] == 'sub':
        result = params[0] - params[1]
    elif request_dict['method'] == 'mul':
        result = params[0] * params[1]
    elif request_dict['method'] == 'div':
        result = params[0] / params[1]
    response = {
        'jsonrpc': '2.0',
        'id': request_dict['id'],
        'result': result
    }
    return json.dumps(response)

