def is_integer(num):
    return isinstance(num, int)

def prime_factorization(num):
    if num < 2:
        return [num]
    smallest_prime_factor = 2
    while smallest_prime_factor * smallest_prime_factor <= num:
        if num % smallest_prime_factor == 0:
            return [smallest_prime_factor] + prime_factorization(num // smallest_prime_factor)
        smallest_prime_factor += 1
    return [num]

def factorize(num_list):
    if not all(is_integer(num) for num in num_list):
        raise ValueError("Input should be a list of integers")
    return [tuple(sorted(prime_factorization(num))) for num in num_list]

