from typing import List

def pack_can_message(message_type: str, message_id: int, payload: List[int]) -> bytes:
    """
    Packs a CAN message and returns the message as a bytes object.
    """
    if message_type == 'data_frame':
        if message_id < 0x00 or message_id > 0x3F:
            raise ValueError('Invalid CAN message ID for data frames: 0x00 - 0x3F')
        if len(payload) > 8:
            raise ValueError('Invalid payload length for data frames: 0 - 8 bytes')
    elif message_type == 'remote_frame':
        if message_id < 0x50 or message_id > 0x5F:
            raise ValueError('Invalid CAN message ID for remote frames: 0x50 - 0x5F')
        if len(payload) > 0:
            raise ValueError('Invalid payload length for remote frames: 0 byte')
    else:
        raise ValueError('Invalid CAN message type')
    message = [message_id, len(payload)] + payload
    message_bytes = bytes(message)

    return message_bytes

