def rgb_to_hsv(r, g, b):
    r_norm = r / 255
    g_norm = g / 255
    b_norm = b / 255
    max_value = max(r_norm, g_norm, b_norm)
    min_value = min(r_norm, g_norm, b_norm)
    if max_value == min_value:
        hue = 0  # Grayscale
    elif max_value == r_norm:
        hue = 60 * ((g_norm - b_norm) / (max_value - min_value)) % 360
    elif max_value == g_norm:
        hue = 60 * ((b_norm - r_norm) / (max_value - min_value)) + 120
    else:
        hue = 60 * ((r_norm - g_norm) / (max_value - min_value)) + 240
    if max_value == 0:
        saturation = 0
    else:
        saturation = 1 - (min_value / max_value)
    value = max_value
    return (hue, saturation, value)

