def is_magic_square(matrix, limit):
    rows = len(matrix)
    cols = len(matrix[0])
    if rows != cols:
        return False
    for row in matrix:
        if sum(row) != limit:
            return False
    for col in range(cols):
        col_sum = sum(row[col] for row in matrix)
        if col_sum != limit:
            return False
    main_diag_sum = sum(matrix[i][i] for i in range(rows))
    if main_diag_sum != limit:
        return False

    secondary_diag_sum = sum(matrix[i][cols - 1 - i] for i in range(rows))
    if secondary_diag_sum != limit:
        return False
    for row in matrix:
        for num in row:
            if num < 0:
                return False

    return True

