from typing import List, Tuple

def sort_tuple_list_to_dict(data: List[Tuple]) -> dict:
    """
    Transforms a list of tuples into a dictionary, where each tuple contains a key-value pair.
    The resulting dictionary is sorted in ascending order of the keys.

    For example, given the input list of tuples `data = [('b', 1), ('a', 1), ('a', 2), ('b', 2)]`,
    the resulting dictionary should be `{'a': [1, 2], 'b': [1, 2]}`.
    """
    result = {}

    for key, value in data:
        if key in result:
            result[key].append(value)
        else:
            result[key] = [value]

    return {key: sorted(values) for key, values in result.items()}

