import numpy as np

def min_max_scaling(arr: np.ndarray, scaled_range: tuple = (0, 1)) -> np.ndarray:
    min_val = np.min(arr)
    max_val = np.max(arr)
    def scale_to_01(x):
        return (x - min_val) / (max_val - min_val)

    def scale_to_m1p1(x):
        return 2 * (x - min_val) / (max_val - min_val) - 1
    scaling_fn = scale_to_01 if scaled_range == (0, 1) else scale_to_m1p1
    return np.vectorize(scaling_fn)(arr)

