    end_minutes = convert_to_minutes(end_time)
    if start_minutes < 0 or start_minutes > 23 * 60 + 59 or end_minutes < 0 or end_minutes > 23 * 60 + 59:
        return False
    if start_minutes >= end_minutes:
        return False
    return True

