def partition(iterable, left, right):
    pivot = iterable[right]
    i = left - 1
    for j in range(left, right):
        if iterable[j] < pivot:
            i += 1
            iterable[i], iterable[j] = iterable[j], iterable[i]
    iterable[i+1], iterable[right] = iterable[right], iterable[i+1]
    return i + 1

def quick_select(iterable, left, right, k):
    if left == right:
        return left
    pivot_index = partition(iterable, left, right)
    if k == pivot_index:
        return k
    elif k < pivot_index:
        return quick_select(iterable, left, pivot_index - 1, k)
    else:
        return quick_select(iterable, pivot_index + 1, right, k)

