def merge_dictionaries(*dicts):
    """
    Merges an arbitrary number of dictionaries into a single one.
    If a key is present in both dictionaries, the value from the second dictionary
    replaces the value in the merged dictionary.
    """

    def _merge_dict(d1, d2):
        for k, v in d2.items():
            if k in d1 and isinstance(d1[k], dict) and isinstance(d2[k], dict):
                _merge_dict(d1[k], d2[k])
            else:
                d1[k] = d2[k]

    merged_dict = {}
    for d in dicts:
        _merge_dict(merged_dict, d)
    return merged_dict

