def factorial(n):
    if n <= 1:
        return 1
    else:
        return n * factorial(n - 1)

def sine_term(x, n):
    sign = 1 if n % 2 == 0 else -1
    return sign * (x ** (2 * n + 1)) / factorial(2 * n + 1)

def my_sine(x):
    result = x
    n = 1
    while abs(sine_term(x, n)) > 1e-16:
        result += sine_term(x, n)
        n += 1
    return result

