import numpy as np

def convert_color(color, source_space, target_space):
    def rgb_to_hsl(color):
        r, g, b = color
        r /= 255
        g /= 255
        b /= 255
        m = min(r, g, b)
        M = max(r, g, b)
        delta = M - m
        if delta == 0:
            h = 0
        elif M == r:
            h = ((g - b) / delta) % 6
        elif M == g:
            h = ((b - r) / delta) + 2
        else:
            h = ((r - g) / delta) + 4
        h *= 60
        if h < 0:
            h += 360
        l = (M + m) / 2
        if delta == 0:
            s = 0
        else:
            s = delta / (1 - abs(2 * l - 1))
        return np.array([h, s * 100, l * 100])

    def hsl_to_rgb(color):
        h, s, l = color
        s /= 100
        l /= 100
        c = (1 - abs(2 * l - 1)) * s
        h /= 60
        x = c * (1 - abs(h % 2 - 1))
        h_floor = int(h)
        if h_floor == 0:
            r, g, b = (c, x, 0)
        elif h_floor == 1:
            r, g, b = (x, c, 0)
        elif h_floor == 2:
            r, g, b = (0, c, x)
        elif h_floor == 3:
            r, g, b = (0, x, c)
        elif h_floor == 4:
            r, g, b = (x, 0, c)
        else:
            r, g, b = (c, 0, x)
        m = l - c / 2
        r += m
        g += m
        b += m
        r *= 255
        g *= 255
        b *= 255
        return np.array([r, g, b])
    if source_space == 'RGB' and target_space == 'HSL':
        return rgb_to_hsl(color)
    elif source_space == 'HSL' and target_space == 'RGB':
        return hsl_to_rgb(color)
    else:
        raise ValueError('Invalid color space conversion')

