import os
import re

def read_batch_config_files(directory_path):
    """
    Reads AWS Batch configuration files from a given directory, parses the configuration,
    and returns a dictionary with the configuration details.
    """
    config_files = []
    config_details = {}

    try:
        for entry in os.scandir(directory_path):
            if entry.is_file():
                with open(entry.path, "r") as file:
                    config_file_version = re.search("(?<=^CONFIG_FILE_VERSION=)\d+", file.read())
                    config_files.append(entry.name)
                    config_details[entry.name] = {
                        "CONFIG_FILE_VERSION": config_file_version.group()
                    }
    except Exception as e:
        print(f"Error: {e}")

    return config_details

