def get_unique_and_duplicates(strings):
    if not isinstance(strings, list):
        raise AssertionError("Input must be a list of strings")

    seen = set()
    duplicates = {}

    for s in strings:
        if s in seen:
            if s in duplicates:
                duplicates[s] += 1
            else:
                duplicates[s] = 1
        else:
            seen.add(s)

    return (set(seen) - set(duplicates.keys()), set(duplicates.keys()))

