from functools import wraps

def zero_warn(msg, warning_level):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            nonlocal warning_level
            nonlocal msg

            result = func(*args, **kwargs)

            if result == 0:
                if warning_level == 1:
                    print(msg)
                elif warning_level == 2:
                    wrapper.call_count += 1
                    if wrapper.call_count % 100 == 0:
                        print(msg)
                elif warning_level == 3:
                    wrapper.call_count += 1
                    if wrapper.call_count % 1000 == 0:
                        print(msg)

            return result

        wrapper.call_count = 0
        return wrapper

    return decorator

