    def __init__(self, dict_list):
        if not isinstance(dict_list, list):
            raise TypeError("Expected a list of dictionaries")
        if not dict_list:
            raise ValueError("The list should not be empty")
        first_keys = set(dict_list[0].keys())
        for dict_ in dict_list:
            if not isinstance(dict_, dict):
                raise TypeError("Expected a list of dictionaries")
            if set(dict_.keys()) != first_keys:
                raise ValueError("Each dictionary should have the same keys")

        self.data = dict_list
        self.column_names = list(first_keys)

    def __len__(self):
        return len(self.data)

    def __getitem__(self, key):
        if isinstance(key, str):
            if key not in self.column_names:
                raise KeyError(f"Column '{key}' not found")
            return [row[key] for row in self.data]
        elif isinstance(key, int):
            if key < 0 or key >= len(self.data):
                raise IndexError("Index out of range")
            return self.data[key]
        elif isinstance(key, tuple) and len(key) == 2:
            row, col = key
            if row < 0 or row >= len(self.data):
                raise IndexError("Row index out of range")
            if col not in self.column_names:
                raise KeyError(f"Column '{col}' not found")
            return self.data[row][col]
        else:
            raise TypeError("Invalid key type")

    def insert_row(self, row_dict):
        if not isinstance(row_dict, dict):
            raise TypeError("Expected a dictionary")
        if set(row_dict.keys()) != set(self.column_names):
            raise ValueError("Row dictionary should have the same keys as the data frame")
        self.data.append(row_dict)

    def delete_row(self, row_index):
        if row_index < 0 or row_index >= len(self.data):
            raise IndexError("Index out of range")
        del self.data[row_index]

