        self.left = left
        self.right = right

def create_binary_tree(num_levels, hash_func):
    if num_levels <= 0:
        return None

    value = hash_func()
    left_child = create_binary_tree(num_levels - 1, hash_func)
    right_child = create_binary_tree(num_levels - 1, hash_func)

    return Node(value, left_child, right_child)

def traverse_tree_dfs(root):
    if not root:
        return []

    stack = [root]
    values = []

    while stack:
        node = stack.pop()
        values.append(node.value)

        if node.right:
            stack.append(node.right)

        if node.left:
            stack.append(node.left)

    return values

