    """
    Checks if two strings are anagrams.
    """
    if len(s1) != len(s2):
        return False

    s1_count = {}
    for c in s1:
        s1_count[c] = s1_count.get(c, 0) + 1

    for c in s2:
        if c not in s1_count or s1_count[c] <= 0:
            return False
        s1_count[c] -= 1

    return True

