def binary_search(input_list, target):
    def search_helper(input_list, target, start, end):
        if start > end:
            return -1

        mid = (start + end) // 2
        if input_list[mid] == target:
            return mid
        elif input_list[mid] > target:
            return search_helper(input_list, target, start, mid - 1)
        else:
            return search_helper(input_list, target, mid + 1, end)

    return search_helper(input_list, target, 0, len(input_list) - 1)

