def page_rank(graph: dict, d: float = 0.85, threshold: float = 1e-6) -> dict:
    num_nodes = len(graph)
    pr = {node: 1 / num_nodes for node in graph}
    diff = 1

    while diff > threshold:
        next_pr = {node: 0 for node in graph}
        for node in graph:
            out_degree = len(graph[node])
            for neighbor in graph[node]:
                next_pr[neighbor] += pr[node] / out_degree
        next_pr = {node: (1 - d) / num_nodes + d * pr_value for node, pr_value in next_pr.items()}
        diff = sum((next_pr[node] - pr[node]) ** 2 for node in graph)
        pr = next_pr

    return pr

