    """Generate all permutations of a string."""
    if len(string) <= 1:
        return [string]
    else:
        permutations = []
        for i in range(len(string)):
            for permutation in get_permutations(string[:i] + string[i+1:]):
                permutations.append(string[i] + permutation)
        return permutations

