from collections import deque

def resolve_dependencies(dependencies):
    graph = {}
    for source, destination in dependencies:
        if source not in graph:
            graph[source] = set()
        graph[source].add(destination)
    queue = deque([dependencies[0][0]])
    transitive_deps = []
    while queue:
        current_package = queue.popleft()
        transitive_deps.append(current_package)
        if current_package in graph:
            for dependency in graph[current_package]:
                if dependency not in transitive_deps:
                    queue.append(dependency)

    return transitive_deps

