def quotient(dividend, divisor):
    if divisor == 0:
        return None

    def subtract(dividend, divisor):
        count = 0
        while dividend >= divisor:
            dividend -= divisor
            count += 1
        return count

    if dividend < 0 and divisor < 0:
        return subtract(-dividend, -divisor)
    elif dividend < 0:
        return -subtract(-dividend, divisor)
    elif divisor < 0:
        return -subtract(dividend, -divisor)
    else:
        return subtract(dividend, divisor)

