import numpy as np

def find_max_gradient(matrix):
    if not isinstance(matrix, np.ndarray):
        raise TypeError('Input must be a Numpy array.')
    if matrix.ndim != 2:
        raise ValueError('Input must be a 2D matrix.')

    max_gradient = -np.inf
    max_gradient_row = -1
    max_gradient_column = -1

    for row in range(matrix.shape[0]):
        for column in range(matrix.shape[1]):
            if column < matrix.shape[1] - 1:
                gradient = abs(matrix[row, column] - matrix[row, column + 1])
                if gradient > max_gradient:
                    max_gradient = gradient
                    max_gradient_row = row
                    max_gradient_column = column
            if row < matrix.shape[0] - 1:
                gradient = abs(matrix[row, column] - matrix[row + 1, column])
                if gradient > max_gradient:
                    max_gradient = gradient
                    max_gradient_row = row
                    max_gradient_column = column

    if max_gradient_row == -1 or max_gradient_column == -1:
        return ()  # No edge gradient found

    return (max_gradient_row, max_gradient_column)

