def quickselect(nums, k):
    if not nums:
        return None
    pivot = nums[0]
    smaller = [n for n in nums[1:] if n < pivot]
    larger = [n for n in nums[1:] if n >= pivot]
    if len(smaller) == k - 1:
        return pivot
    elif len(smaller) > k - 1:
        return quickselect(smaller, k)
    else:
        return quickselect(larger, k - len(smaller) - 1)

def find_median(nums):
    if not nums:
        return None
    n = len(nums)
    if n % 2 == 0:
        return (quickselect(nums, n // 2) + quickselect(nums, n // 2 + 1)) / 2
    else:
        return quickselect(nums, n // 2 + 1)

