def find_closest_element(array, target):
    if target < array[0]:
        return 0
    if target > array[-1]:
        return len(array) - 1

    left = 0
    right = len(array) - 1
    while left < right:
        mid = left + (right - left) // 2
        if target == array[mid]:
            return mid
        elif target < array[mid]:
            right = mid
        else:
            left = mid + 1
    if left > 0 and abs(array[left] - target) == abs(array[left - 1] - target):
        return min(left, left - 1)
    else:
        return left

