from typing import Any, Set

def find_values_greater_than(dictionary: dict, threshold: int) -> Set[Any]:
    """
    Recursively traverses a dictionary and returns a set of all values that are greater
    than the specified threshold.
    """
    values = set()

    for value in dictionary.values():
        if isinstance(value, dict):
            values |= find_values_greater_than(value, threshold)
        elif isinstance(value, (list, tuple)):
            for item in value:
                if isinstance(item, dict):
                    values |= find_values_greater_than(item, threshold)
                else:
                    values.add(item)
        else:
            values.add(value)

    return {value for value in values if value > threshold}

