class Graph:
    def __init__(self):
        self.nodes = {}

    def add_edge(self, src, dst):
        if src not in self.nodes:
            self.nodes[src] = []
        self.nodes[src].append(dst)

    def get_neighbors(self, node):
        return self.nodes.get(node, [])

    def has_node(self, node):
        return node in self.nodes

    def get_nodes(self):
        return self.nodes.keys()

def dfs(graph, start):
    """Depth-first search"""
    visited = set()
    stack = [start]

    while stack:
        node = stack.pop()
        if node not in visited:
            visited.add(node)
            stack.extend(graph.get_neighbors(node))

    return visited

def bfs(graph, start):
    """Breadth-first search"""
    visited = set()
    queue = [start]

    while queue:
        node = queue.pop(0)
        if node not in visited:
            visited.add(node)
            queue.extend(graph.get_neighbors(node))

    return visited

