def make_palindrome(string):
    def helper(i, j):
        if i >= j:
            return 0
        if (i, j) in cache:
            return cache[(i, j)]
        if string[i] == string[j]:
            cache[(i, j)] = helper(i+1, j-1)
            return cache[(i, j)]
        else:
            cache[(i, j)] = 1 + min(helper(i+1, j), helper(i, j-1))
            return cache[(i, j)]

    cache = {}
    return helper(0, len(string)-1)

