from math import sqrt

def largest_prime_factor(n):
    for i in range(2, int(sqrt(n)) + 1):
        if n % i == 0:
            return i
    return n

def solve_problem(grid):
    cache = [[0 for _ in range(len(grid))] for _ in range(len(grid))]
    visited = [[False for _ in range(len(grid))] for _ in range(len(grid))]
    def get_adjacent_cells(i, j):
        directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]
        for di, dj in directions:
            ni, nj = i + di, j + dj
            if 0 <= ni < len(grid) and 0 <= nj < len(grid):
                yield ni, nj
    def process_cell(i, j):
        if visited[i][j]:
            return cache[i][j]
        visited[i][j] = True
        adjacent_factors = []
        for ni, nj in get_adjacent_cells(i, j):
            adjacent_factors.append(process_cell(ni, nj))
        cache[i][j] = largest_prime_factor(max(adjacent_factors))
        return cache[i][j]
    for i in range(len(grid)):
        for j in range(len(grid)):
            process_cell(i, j)
    total = 0
    for i in range(len(grid)):
        for j in range(len(grid)):
            adjacent_factors = []
            for ni, nj in get_adjacent_cells(i, j):
                adjacent_factors.append(cache[ni][nj])
            total += max(adjacent_factors)
    return total

