def next_composite_gen(**kwargs):
    """
    Creates a generator that yields the next composite number.

    Keyword arguments:
    - `kwargs`: An arbitrary number of keyword arguments, where each argument is a function that takes a number as input and determines whether it is composite or not.

    Returns:
    - A generator that yields the next composite number that passes all the given tests.
    """
    def is_composite(num: int) -> bool:
        if num < 2:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return True
        return False

    tests = list(kwargs.values())
    for num in (x for x in range(2, 1000000000) if is_composite(x)):
        for test in tests:
            if not test(num):
                break
        else:
            yield num

