def search(text, pattern):
    """
    Searches for a pattern string in a text string and returns the first matching substring in the format
    'start-end: match', where 'start' and 'end' are the start and end indices of the matching substring,
    and 'match' is the matching substring. If no match is found, returns an empty string. If the starting
    and ending indices are the same, formats the result as 'index: match', where 'index' is the index of
    the matching character and 'match' is the matching character.
    """
    def search_matches():
        i, j = 0, 0
        while i < len(text):
            if text[i] == pattern[j]:
                i += 1
                j += 1
                if j == len(pattern):
                    start = i - len(pattern)
                    end = i - 1
                    match = text[start:end+1]
                    if start == end:
                        result = f"{start}: {match}"
                    else:
                        result = f"{start}-{end}: {match}"
                    yield result
                    j = 0
            else:
                i = i - j + 1
                j = 0
    try:
        return next(search_matches())
    except StopIteration:
        return ""

