def check_valid_string(string: str = '') -> bool:
    if not isinstance(string, str):
        return False

    stack = []

    for char in string:
        if char == '(' or char == '[' or char == '{':
            stack.append(char)
        elif char == ')' or char == ']' or char == '}':
            if len(stack) == 0:
                return False
            top = stack[-1]

            if top == '(' and char != ')' or top == '[' and char != ']' or top == '{' and char != '}':
                return False

            stack.pop()
        else:
            continue

    return len(stack) == 0

