def transitive_closure(adjacency_dict):
    vertices = list(adjacency_dict.keys())
    dist = [[float('inf')] * len(vertices) for _ in range(len(vertices))]
    for i, vertex in enumerate(vertices):
        for neighbor in adjacency_dict[vertex]:
            j = vertices.index(neighbor)
            dist[i][j] = 1
    for k in range(len(vertices)):
        for i in range(len(vertices)):
            for j in range(len(vertices)):
                dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j])
    closure = {}
    for i, vertex in enumerate(vertices):
        closure[vertex] = set()
        for j, neighbor in enumerate(vertices):
            if dist[i][j] < float('inf'):
                closure[vertex].add(neighbor)

    return closure

