def rotated_binary_search(nums, target):
    pivot = 0
    for i in range(1, len(nums)):
        if nums[i] < nums[i - 1]:
            pivot = i
            break
    if target < nums[pivot] or target > nums[pivot - 1]:
        return -1
    if target >= nums[0]:
        start, end = 0, pivot - 1
    else:
        start, end = pivot, len(nums) - 1
    while start <= end:
        mid = (start + end) // 2
        if nums[mid] == target:
            return mid
        elif nums[mid] < target:
            start = mid + 1
        else:
            end = mid - 1
    return -1

