def hexadecimal_to_binary(hexadecimal_string):
    hexadecimal_string = hexadecimal_string.upper()  # Convert to uppercase
    binary_string = ''
    for char in hexadecimal_string:
        if char in '0123456789':
            binary_string += bin(int(char))[2:].zfill(4)  # Convert the digit to binary
        elif char in 'ABCDEF':
            binary_string += bin(ord(char) - ord('A') + 10)[2:].zfill(4)  # Convert the letter to binary
        else:
            raise ValueError('Invalid hexadecimal character: {}'.format(char))
    return binary_string.zfill(len(binary_string) + (4 - len(binary_string) % 4) % 4)  # Pad with zeros if the length is not a multiple of 4

