import json

def remove_non_ascii(json_string):
    data = json.loads(json_string)
    def remove_non_ascii_from_string(s):
        return ''.join(c for c in s if ord(c) < 128)
    def remove_non_ascii_from_structure(structure):
        if isinstance(structure, str):
            return remove_non_ascii_from_string(structure)
        elif isinstance(structure, dict):
            return {k: remove_non_ascii_from_structure(v) for k, v in structure.items()}
