import numpy as np

def reconstruct_fes(energy_matrix):
    fes_matrix = np.zeros(energy_matrix.shape)
    converged = False
    while not converged:
        updated_fes_matrix = np.zeros(energy_matrix.shape)
        for i in range(energy_matrix.shape[0]):
            for j in range(energy_matrix.shape[1]):
                value = energy_matrix[i, j]
                if value < 0:
                    updated_fes_matrix[i, j] = value + 1
                elif value == 0:
                    updated_fes_matrix[i, j] = 1
                else:
                    updated_fes_matrix[i, j] = value - 1
        if np.array_equal(fes_matrix, updated_fes_matrix):
            converged = True
        else:
            fes_matrix = updated_fes_matrix

    return fes_matrix

