import re

def is_version_string(version_info):
    pattern = r"^[\w-]+:(\d+\.){2}\d+$"
    return re.match(pattern, version_info) is not None

def extract_version_number(version_info):
    if not is_version_string(version_info):
        return None
    version_name, version_info = version_info.split(':')
    major, minor, patch = version_info.split('.')
    for value in (major, minor, patch):
        if not value.isdigit():
            return None
    return f"{major}.{minor}.{patch}"

def extract_version_number_with_error_handling(version_info):
    try:
        return extract_version_number(version_info)
    except:
        return None

