class TreeNode:
    def __init__(self, value):
        self.value = value
        self.parent = None
        self.children = []

    def add_child(self, child):
        child.parent = self
        self.children.append(child)

    def get_children(self):
        return self.children

    def get_nodes_at_depth(self, depth):
        if depth == 0:
            return [self]

        nodes = []
        for child in self.children:
            nodes.extend(child.get_nodes_at_depth(depth - 1))
        return nodes

    def get_lowest_common_ancestor(self, other_node):
        ancestors = set()
        node = self
        while node:
            ancestors.add(node)
            node = node.parent

        node = other_node
        while node:
            if node in ancestors:
                return node
            node = node.parent

