def bisection(f, a, b, epsilon=1e-8):
    if a > b or a == b:
        raise ValueError("Invalid interval")
    if f(a) < f(b):
        sign = 1
    elif f(a) > f(b):
        sign = -1
    else:
        return a
    while b - a > epsilon:
        c = (a + b) / 2
        if sign * f(c) < 0:
            b = c
        else:
            a = c
    return (a + b) / 2

