import keyword

def check_properties(obj):
    """
    Checks a given object for certain properties, and if those properties are not present,
    it should return the object as-is. If the properties are present, it should return a
    new object with those properties removed. If the object is empty, it should return
    an empty object.
    """
    if not obj:
        return {}
    present_props = []
    for prop in obj.keys():
        if keyword.iskeyword(prop):
            present_props.append(prop)

    if not present_props:
        return obj
    new_obj = {}
    for prop, value in obj.items():
