import numpy as np

def row_wise_maximum(A):
    if A.size == 0:
        return []

    row_maxima = []
    for row_idx in range(A.shape[0]):
        current_max = float('-inf')
        for col_idx in range(A.shape[1]):
            if A[row_idx, col_idx] > current_max:
                current_max = A[row_idx, col_idx]
