def estimate_transition_probabilities(utterances):
    counts = {}
    for i in range(len(utterances) - 1):
        current_speaker = utterances[i][0]
        next_speaker = utterances[i+1][0]
        if current_speaker not in counts:
            counts[current_speaker] = {}
        counts[current_speaker][next_speaker] = counts[current_speaker].get(next_speaker, 0) + 1
    probabilities = {}
    for speaker, next_speaker_counts in counts.items():
        total_transitions = sum(next_speaker_counts.values())
        probabilities[speaker] = {next_speaker: count / total_transitions for next_speaker, count in next_speaker_counts.items()}

    return probabilities

