def copy_prefixed_files_and_dirs(src_path, dest_path, prefix):
    if not os.path.exists(src_path):
        raise FileNotFoundError(f"Source directory not found: {src_path}")
    if not os.path.exists(dest_path):
        raise FileNotFoundError(f"Destination directory not found: {dest_path}")
    if not os.path.isdir(src_path):
        raise ValueError(f"Source path is not a directory: {src_path}")

    for file_or_dir in os.listdir(src_path):
        full_src_path = os.path.join(src_path, file_or_dir)
        full_dest_path = os.path.join(dest_path, file_or_dir)
        if file_or_dir.startswith(prefix):
            if os.path.isfile(full_src_path):
                shutil.copy(full_src_path, full_dest_path)
            elif os.path.isdir(full_src_path):
                os.makedirs(full_dest_path, exist_ok=True)
                copy_prefixed_files_and_dirs(full_src_path, full_dest_path, prefix)

