    print(" ".join(args))
    return 0

def change_directory(args):
    if len(args) > 2:
        raise ValueError(f"Too many arguments for cd: {args}")
    elif len(args) == 0:
        path = os.getenv("HOME")
    else:
        path = args[0]
    os.chdir(path)
    return 0

def exit_program(args):
    if len(args) > 1:
        raise ValueError(f"Too many arguments for exit: {args}")
    elif len(args) == 0:
        return 0
    else:
        return int(args[0])

def simulate_program(commands):
    for command in commands:
        exit_code = execute_command(command)
        if exit_code != 0:
            return exit_code
    return 0

