def generate_texture_shader_code(num_channels=4, texture_type="uniform"):
    shader_code = """
    // Define the uniform sampler2D variable
    uniform sampler2D texture_sampler;

    // Define the texture coordinates variable
    vec2 uv;

    // Function to compute the texture coordinates in NDC
    vec2 compute_ndc_coords(vec2 uv) {
        return uv * 2.0 - 1.0;
    }

    // Main function to render the texture on a square mesh
    void main() {
        // Compute the texture coordinates in NDC
        vec2 ndc_coords = compute_ndc_coords(uv);

        // Sample the texture and get the color
        vec4 color = texture(texture_sampler, ndc_coords);
    }
    """
    if num_channels == 1:
        shader_code += "gl_FragColor = vec4(color.r, color.r, color.r, 1.0);"
    elif num_channels == 2:
        shader_code += "gl_FragColor = vec4(color.rg, color.rg, 1.0);"
    elif num_channels == 3:
        shader_code += "gl_FragColor = vec4(color.rgb, 1.0);"
    else:
        shader_code += "gl_FragColor = color;"
    if texture_type == "uniform":
        shader_code += """
        // Declare and initialize the uniform sampler2D variable
        uniform sampler2D texture_sampler;
        """
    elif texture_type == "attribute":
        shader_code += """
        // Declare and initialize the attribute variable
        attribute vec2 texture_coords;
        """

    return shader_code

