def factorization(num):
    if not isinstance(num, int) or num <= 0:
        raise ValueError("Input must be a positive integer.")
    prime_factors = {}
    def find_prime_factors(n, factors):
        if n == 1:
            return

        for i in range(2, n + 1):
            if n % i == 0:
                factors[i] = factors.get(i, 0) + 1
                find_prime_factors(n // i, factors)
                break
    find_prime_factors(num, prime_factors)
    latex_string = ""
    for prime, exponent in prime_factors.items():
        latex_string += f"{prime}" if exponent == 1 else f"{prime}^{exponent}"
        latex_string += " \times "
    if latex_string:
        latex_string = latex_string[:-7]

