from collections import Counter

def word_count(sentence, word_list):
    if not isinstance(sentence, str):
        raise TypeError('The sentence must be a string.')
    if not isinstance(word_list, list) or not all(isinstance(word, str) for word in word_list):
        raise TypeError('The word_list must be a list of strings.')
    def count_word(word):
        count = 0
        for w in sentence.split():
            if w.lower() == word.lower():
                count += 1
        return count
    return {word: count_word(word) for word in word_list}

